import spidev

MIN_CHANNEL = 0
MAX_CHANNEL = 7
MAX_COUNT = 4095


def setup_spi():
    """Initialize and return an SPI connection."""
    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.mode = 0
        spi.max_speed_hz = 1000000
        spi.bit_order = 'msb_first'
        return spi
    except Exception as e:
        print(f"SPI setup failed: {e}")
        return None


def read_adc_channel(spi, channel):
    """Read raw ADC value from the specified channel."""
    if spi is None:
        print("SPI not initialized")
        return -1

    if not MIN_CHANNEL <= channel <= MAX_CHANNEL:
        print(f"Invalid channel: {channel}. Must be between {MIN_CHANNEL} and {MAX_CHANNEL}.")
        return -1

    try:
        adc = spi.xfer2([6 | (channel & 4) >> 2, (channel & 3) << 6, 0])
        data = ((adc[1] & 15) << 8) + adc[2]
        return data
    except Exception as e:
        print(f"SPI transfer failed: {e}")
        return -1


def read_normalized_channel(spi, channel):
    """Read normalized ADC value from the specified channel."""
    raw_value = read_adc_channel(spi, channel)
    if raw_value == -1:
        return -1
    return raw_value / (MAX_COUNT + 1)


def main():
    """Main function to read and print ADC values."""
    spi = setup_spi()

    try:
        raw_value0 = read_adc_channel(spi, 0)
        normalized_value0 = read_normalized_channel(spi, 0)

        if raw_value0 != -1 and normalized_value0 != -1:
            print(f"Channel 0: Raw={raw_value0}, Normalized={normalized_value0:.4f}")

    finally:
        if spi:
            spi.close()


if __name__ == "__main__":
    main()

