import smbus
import time

bus = smbus.SMBus(1)
addr = 0x48

def swap(a):
    return ((a & 0xff00) >> 8) | ((a & 0x00ff) << 8)

def readAdc(c):
    config = 0x8583 | (c << 12)
    bus.write_word_data(addr, 1, swap(config))
    while True:
        if swap(bus.read_word_data(addr, 0)) & 0x8000:
            break
    return swap(bus.read_word_data(addr, 0)) & 0x0fff

while True:
    s = ""
    for i in range(4):
        s += str(i) + ": %05d" % readAdc(i) + "  "
    print(s)
    time.sleep(0.05)

