#!/usr/bin/python

import time
import logging
import sys
import smbus
from Adafruit_I2C import Adafruit_I2C
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants for ADS1015
ADS1015_DEFAULT_ADDRESS = 0x48
ADS1015_IC = 0x00
ADS1015_0 = 0x00
ADS1015_1 = 0x01
ADS1015_2 = 0x02
ADS1015_3 = 0x03
ADS1015_START = 0x01
ADS1015_STOP = 0x00
ADS1015_SINGLE_ENDED = 0x03
ADS1015_DIFFERENTIAL = 0x02
ADS1015_BUS_ERROR = 0x00
ADS1015_COMP_QUE_DISABLE = 0x00
ADS1015_COMP_QUE_ENABLE = 0x80
ADS1015_COMP_POL_ACTIVE_LOW = 0x00
ADS1015_COMP_POL_ACTIVE_HIGH = 0x40
ADS1015_COMP_LAT_NON_LATCHING = 0x00
ADS1015_COMP_LAT_LATCHING = 0x20
ADS1015_COMP_QUE_1_CONV = 0x08
ADS1015_COMP_QUE_2_CONV = 0x10
ADS1015_COMP_QUE_4_CONV = 0x18
PGA_VALUES = [6144, 4096, 2048, 1024, 512, 256, 128, 0]  # Valid PGA values
SPS_VALUES = [128, 250, 490, 920, 1600, 2400, 3300, 3600, 5000, 9200, 16000, 21000, 46000]  # Valid SPS values

def _validate_input(value, valid_values, value_name):
    """Validates input against a list of valid values."""
    if value not in valid_values:
        raise ValueError(f"Invalid {value_name}: {value}.  Must be one of {valid_values}")


def _swap_bytes(value):
    """Swaps the high and low bytes of a 16-bit value."""
    return ((value & 0xFF00) >> 8) | ((value & 0x00FF) << 8)


def _read_adc(i2c_device, address, register):
    """Reads a register from the ADS1015."""
    try:
        return i2c_device.readList(address, register, 2)
    except Exception as e:
        logger.error(f"Error reading from ADS1015 at address {address}, register {register}: {e}")
        raise


def _write_adc(i2c_device, address, register, value):
    """Writes a value to a register on the ADS1015."""
    try:
        i2c_device.writeList(address, register, [(value >> 8) & 0xFF, value & 0xFF])
    except Exception as e:
        logger.error(f"Error writing to ADS1015 at address {address}, register {register}: {e}")
        raise



def _configure_adc(i2c_device, address, config):
    """Configures the ADS1015 with the given configuration."""
    try:
        _write_adc(i2c_device, address, 1, _swap_bytes(config))
        logger.debug(f"ADS1015 configured with: {config}")
    except Exception as e:
        logger.error(f"Error configuring ADS1015: {e}")
        raise



def _read_conversion_result(i2c_device, address):
    """Reads and returns the conversion result from the ADS1015."""
    try:
        result = _read_adc(i2c_device, address, 0)
        return _swap_bytes((result[0] << 8) | result[1])
    except Exception as e:
        logger.error(f"Error reading conversion result: {e}")
        raise



def _create_adc_reader(i2c_device, address):
    """Creates a function to read the ADC value with error handling."""
    def read_adc():
        try:
            return _read_conversion_result(i2c_device, address)
        except Exception as e:
            logger.error(f"Error during ADC read: {e}")
            return None  # Or raise the exception depending on desired behavior
    return read_adc



def _create_config(channel, pga, sps, continuous_mode, active_low, traditional_mode, latching,
                    num_readings, comparator_config):

    config = ADS1015_DEFAULT_CONFIG  # Start with default config

    # Input multiplexer config
    if 0 <= channel <= 3:
        config |= {
            0: ADS1015_0,
            1: ADS1015_1,
            2: ADS1015_2,
            3: ADS1015_3,
        }[channel]
    else:
        raise ValueError("Invalid channel. Must be between 0 and 3.")

    # Programmable gain amplifier config
    _validate_input(pga, PGA_VALUES, "pga")
    config |= PGA_VALUES.index(pga) << 5


    # Sample per second config
    _validate_input(sps, SPS_VALUES, "sps")
    sps_index = SPS_VALUES.index(sps)
    config |= sps_index << 11


    # Single-ended vs differential config
    if continuous_mode:
        config |= ADS1015_SINGLE_ENDED
    else:
        config |= ADS1015_DIFFERENTIAL


    # Comparator config
    if comparator_config is not None:
        threshold, threshold_high, threshold_low, hysteresis = comparator_config

        config |= ADS1015_COMP_QUE_DISABLE  # Disable comparator queue

        if latching:
            config |= ADS1015_COMP_LAT_LATCHING
        else:
            config |= ADS1015_COMP_LAT_NON_LATCHING

        if active_low:
            config |= ADS1015_COMP_POL_ACTIVE_LOW
        else:
            config |= ADS1015_COMP_POL_ACTIVE_HIGH

        if traditional_mode:
            config |= ADS1015_COMP_QUE_ENABLE
        else:
            config |= ADS1015_COMP_QUE_DISABLE  # Disable comparator queue for windowing

        config |= num_readings << 10


        # Set threshold value (12-bit resolution)
        threshold_value = int((threshold / pga) * 2048)  # Convert threshold to a 12-bit value
        config |= threshold_value & 0x0FFF  # Mask to 12 bits


        # Set high threshold for windowing mode
        if not traditional_mode:
            threshold_high_value = int((threshold_high / pga) * 2048)
            threshold_low_value = int((threshold_low / pga) * 2048)

            # Combine high and low threshold values
            config |= (threshold_high_value & 0x0FFF) << 4
            config |= (threshold_low_value & 0x0FFF)


    return config



def _configure_and_read(i2c_device, address, config):
    """Configures the ADS1015 and returns a function to read the ADC value."""

    _configure_adc(i2c_device, address, config)

    if config & ADS1015_START:
        logger.info("Starting continuous conversion...")
    else:
        logger.info("Starting single conversion...")

    read_adc = _create_adc_reader(i2c_device, address)

    return read_adc



def _setup_i2c(address=ADS1015_DEFAULT_ADDRESS, busnum=1, debug=False):
    """Sets up the I2C bus and returns an I2C device."""
    try:
        i2c_device = Adafruit_I2C(address, busnum=busnum, debug=debug)
        logger.info(f"Connected to ADS1015 at address {address}")
        return i2c_device
    except Exception as e:
        logger.error(f"Error setting up I2C: {e}")
        raise


ADS1015_DEFAULT_CONFIG = 0x8583  # Default config: 6144mV, 250SPS, AIN0


def read_adc_single_ended(i2c_device, address, channel=0, pga=6144, sps=250):
    """Reads single-ended ADC value from the given channel."""
    config = _create_config(channel, pga, sps, continuous_mode=False, active_low=False,
                             traditional_mode=True, latching=False, num_readings=1,
                             comparator_config=None)
    config |= ADS1015_START
    read_adc = _configure_and_read(i2c_device, address, config)
    if read_adc:
        return read_adc()
    return None


def start_continuous_conversion(i2c_device, address, channel=0, pga=6144, sps=250):
    """Starts continuous conversion mode."""
    config = _create_config(channel, pga, sps, continuous_mode=True, active_low=False,
                             traditional_mode=True, latching=False, num_readings=1,
                             comparator_config=None)
    config |= ADS1015_START
    return _configure_and_read(i2c_device, address, config)



def get_last_conversion_results(i2c_device, address):
    """Gets the last conversion result."""
    return _read_conversion_result(i2c_device, address)



def start_single_ended_comparator(i2c_device, address, channel=0, threshold=100,
                                   threshold_high=None, threshold_low=None, hysteresis=0,
                                   pga=6144, sps=250, active_low=True, traditional_mode=True,
                                   latching=False, num_readings=1):
    """Starts single-ended comparator mode."""

    comparator_config = (threshold, threshold_high, threshold_low, hysteresis)

    config = _create_config(channel, pga, sps, continuous_mode=False, active_low=active_low,
                             traditional_mode=traditional_mode, latching=latching,
                             num_readings=num_readings, comparator_config=comparator_config)
    config |= ADS1015_START
    return _configure_and_read(i2c_device, address, config)



if __name__ == '__main__':
    i2c_device = None
    try:
        i2c_device = _setup_i2c()
        value = read_adc_single_ended(i2c_device, ADS1015_DEFAULT_ADDRESS, channel=0, pga=6144, sps=250)
        logger.info(f"ADC Value: {value}")
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if i2c_device is not None:
            i2c_device.close()

