import time
import RPi.GPIO as GPIO
import smbus2

# I2C address of the PCF8574 expander
PCF8574_ADDRESS = 0x20

# GPIO pin connected to the PCF8574 interrupt (INT) pin
PCF8574_INTERRUPT_PIN = 17

# I2C bus number (usually 1 on Raspberry Pi)
I2C_BUS_NUMBER = 1


def initialize_gpio():
    """Initialize GPIO settings for the interrupt pin."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PCF8574_INTERRUPT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)


def initialize_i2c_bus(bus_number):
    """Initialize the I2C bus."""
    try:
        bus = smbus2.SMBus(bus_number)
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def read_proximity_sensors(bus, address):
    """Read the state of the proximity sensors connected to the PCF8574."""
    try:
        sensor_values = bus.read_byte(address)
        return sensor_values
    except Exception as e:
        print(f"Error reading proximity sensors: {e}")
        return None


def handle_obstacle_detection(sensor_values):
    """Print a message for each active proximity sensor."""
    if sensor_values is None:
        return

    for sensor_number in range(8):
        if (sensor_values >> sensor_number) & 1 == 0:  # Active low
            print(f"Obstacle detected by sensor {sensor_number}")


def main():
    """Main function to continuously monitor proximity sensors."""
    initialize_gpio()
    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)

    if i2c_bus is None:
        GPIO.cleanup()
        return

    try:
        while True:
            sensor_data = read_proximity_sensors(i2c_bus, PCF8574_ADDRESS)
            handle_obstacle_detection(sensor_data)
            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        if i2c_bus:
            i2c_bus.close()
        GPIO.cleanup()
