import sys
import time
import logging
import cv2
import pygame.mixer
import RPi.GPIO as GPIO
from threading import Thread, Lock
import select

# Project-specific modules
import config
import face
import hardware

# Constants
INPUT_TIMEOUT_SECONDS = 0.0  # Non-blocking input check

# Audio channel constants
CHANNEL_A = 0
CHANNEL_B = 1
CHANNEL_C = 2

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class DoorAccessController:
    """
    Controls door access based on face recognition and a button.
    """

    def __init__(self):
        """Initializes the controller."""
        self.audio_manager = AudioManager()
        self.camera_manager = CameraManager()
        self.lock_manager = LockManager()
        self.running = True

    def initialize(self):
        """Initializes all components."""
        try:
            self.audio_manager.initialize()
            self.camera_manager.initialize()
            self.lock_manager.initialize()
            return True
        except Exception as e:
            logger.error(f"Initialization failed: {e}", exc_info=True)
            return False

    def run(self):
        """Runs the main access control loop."""
        self.audio_manager.play_sound(self.audio_manager.SOUNDS_WELCOME)
        logger.info("Door access controller started.")

        try:
            while self.running:
                if self.lock_manager.is_button_up() or self.is_letter_input('l'):
                    self.process_access_grant()
                time.sleep(0.1)  # Reduced sleep for responsiveness
        except KeyboardInterrupt:
            logger.info("Keyboard interrupt detected. Exiting.")
        except Exception as e:
            logger.error(f"Unexpected error: {e}", exc_info=True)
        finally:
            self.cleanup()

    def is_letter_input(self, letter: str) -> bool:
        """Checks for specific character input on stdin (non-blocking)."""
        try:
            rlist, _, _ = select.select([sys.stdin], [], [], INPUT_TIMEOUT_SECONDS)
            if rlist:
                input_char = sys.stdin.read(1)
                return input_char.lower() == letter.lower()
            return False
        except Exception as e:
            logger.error(f"Error reading input: {e}", exc_info=True)
            return False

    def process_access_grant(self):
        """Processes a potential access grant."""
        if not self.lock_manager.is_locked:
            logger.info("Button pressed, but door is already unlocked.")
            return

        logger.info("Button pressed, initiating face recognition.")
        self.audio_manager.play_sound(self.audio_manager.SOUNDS_WAIT)

        image = self.camera_manager.capture_image()
        if image is None:
            logger.error("Failed to capture image for face recognition.")
            self.audio_manager.play_sound(self.audio_manager.SOUNDS_FAIL)
            return

        gray_image = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        face_coordinates = face.detect_single(gray_image)

        if face_coordinates is None:
            logger.warning("Could not detect a single face.")
            self.audio_manager.play_sound(self.audio_manager.SOUNDS_FAIL)
            return

        x, y, w, h = face_coordinates
        cropped_face = face.crop(gray_image, x, y, w, h)
        resized_face = face.resize(cropped_face)

        label, confidence = self.camera_manager.predict(resized_face)

        logger.info(f"Predicted label: {label}, Confidence: {confidence}")

        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
            logger.info("Face recognized positively. Unlocking door.")
            self.lock_manager.unlock()
            self.audio_manager.play_sound(self.audio_manager.SOUNDS_OK)
        else:
            logger.info("Face not recognized. Locking door.")
            self.audio_manager.play_sound(self.audio_manager.SOUNDS_LATER)

    def cleanup(self):
        """Releases resources."""
        logger.info("Cleaning up resources.")
        self.camera_manager.close()
        self.lock_manager.close()
        self.audio_manager.quit()
        GPIO.cleanup()  # Clean up GPIO settings


class AudioManager:
    """Manages audio playback."""

    def __init__(self):
        """Initializes the audio manager."""
        self.mixer = pygame.mixer
        self.sounds = {
            "welcome": "audio/welcome.wav",
            "wait": "audio/wait.wav",
            "later": "audio/later.wav",
            "ok": "audio/ok.wav",
            "live": "audio/live.wav",
        }
        self.channels = {
            CHANNEL_A: self.mixer.Channel(1),
            CHANNEL_B: self.mixer.Channel(2),
            CHANNEL_C: self.mixer.Channel(3),
        }
        self.sound_objects = {}

    def initialize(self):
        """Initializes the Pygame mixer and loads sounds."""
        try:
            self.mixer.init(frequency=48000, size=-16, channels=1, buffer=1024)
            for name, path in self.sounds.items():
                try:
                    self.sound_objects[name] = self.mixer.Sound(path)
                except Exception as e:
                    logger.error(f"Error loading sound '{path}': {e}", exc_info=True)
                    raise  # Re-raise to halt initialization
        except Exception as e:
            logger.error(f"Error initializing audio: {e}", exc_info=True)
            raise

    def play_sound(self, sound_name: str, channel: int = CHANNEL_A):
        """Plays a sound on the specified channel."""
        try:
            sound = self.sound_objects.get(sound_name)
            if sound:
                self.channels[channel].play(sound)
            else:
                logger.warning(f"Sound '{sound_name}' not loaded.")
        except Exception as e:
            logger.error(f"Error playing sound '{sound_name}': {e}", exc_info=True)

    def play_live_loop(self):
        """Plays the 'live' sound continuously on a separate thread."""
        while True:
            self.play_sound("live", CHANNEL_B)
            time.sleep(0.05)

    def quit(self):
        """Stops all sounds and quits the mixer."""
        try:
            self.mixer.quit()
        except Exception as e:
            logger.error(f"Error quitting mixer: {e}", exc_info=True)


class CameraManager:
    """Manages the camera."""

    def __init__(self):
        """Initializes the camera manager."""
        self.camera = None

    def initialize(self):
        """Initializes the camera."""
        try:
            self.camera = config.get_camera()
            if self.camera is None:
                raise ValueError("Failed to initialize camera.")
        except Exception as e:
            logger.error(f"Error initializing camera: {e}", exc_info=True)
            raise

    def capture_image(self) -> cv2.Mat:
        """Captures an image from the camera."""
        try:
            ret, image = self.camera.read()
            if not ret:
                raise IOError("Failed to capture image.")
            return image
        except Exception as e:
            logger.error(f"Error capturing image: {e}", exc_info=True)
            return None

    def predict(self, image: cv2.Mat) -> tuple[int, float]:
        """Performs face recognition on the given image."""
        try:
            model = cv2.face.EigenFaceRecognizer_create()
            model.read(config.TRAINING_FILE)
            label, confidence = model.predict(image)
            return label, confidence
        except Exception as e:
            logger.error(f"Error predicting face: {e}", exc_info=True)
            return -1, float('inf')  # Indicate failure

    def close(self):
        """Releases the camera."""
        try:
            if self.camera is not None:
                self.camera.release()
        except Exception as e:
            logger.error(f"Error releasing camera: {e}", exc_info=True)


class LockManager:
    """Manages the door lock."""

    def __init__(self):
        """Initializes the lock manager."""
        self.lock = None
        self.is_locked = True

    def initialize(self):
        """Initializes the lock."""
        try:
            self.lock = hardware.DoorLock()
        except Exception as e:
            logger.error(f"Error initializing lock: {e}", exc_info=True)
            raise

    def unlock(self):
        """Unlocks the door."""
        try:
            self.lock.unlock()
            self.is_locked = False
            logger.info("Door unlocked.")
        except Exception as e:
            logger.error(f"Error unlocking door: {e}", exc_info=True)

    def lock(self):
        """Locks the door."""
        try:
            self.lock.lock()
            self.is_locked = True
            logger.info("Door locked.")
        except Exception as e:
            logger.error(f"Error locking door: {e}", exc_info=True)

    def is_button_up(self) -> bool:
        """Checks if the button is pressed."""
        try:
            return self.lock.is_button_up()
        except Exception as e:
            logger.error(f"Error reading button state: {e}", exc_info=True)
            return False

    def close(self):
        """Releases the lock resources."""
        try:
            if self.lock is not None:
                self.lock.close()
        except Exception as e:
            logger.error(f"Error closing lock: {e}", exc_info=True)


if __name__ == "__main__":
    controller = DoorAccessController()
    if controller.initialize():
        controller.run()

