import cv2
import sys
from typing import Tuple, List
from contextlib import contextmanager

@contextmanager
def open_camera(gpio=0, resolution: Tuple[int, int] = (640, 480), scale: float = 1.1) -> cv2.VideoCapture:
    """Context manager for opening and releasing the camera."""
    try:
        camera = cv2.VideoCapture(gpio, cv2.CAP_V4L2)
        if not camera.isOpened():
            raise IOError("Could not open camera.")
        camera.set(cv2.CAP_PROP_FRAME_WIDTH, resolution[0])
        camera.set(cv2.CAP_PROP_FRAME_HEIGHT, resolution[1])
        yield camera
    finally:
        if camera.isOpened():
            camera.release()


def load_cascade(cascade_path: str) -> cv2.CascadeClassifier:
    """Loads the face cascade classifier."""
    try:
        cascade = cv2.CascadeClassifier(cascade_path)
        if cascade.empty():
            raise IOError(f"Unable to load cascade file: {cascade_path}")
        return cascade
    except Exception as e:
        raise IOError(f"Error loading cascade: {e}")


def detect_faces(image: any, cascade: cv2.CascadeClassifier, scale_factor: float = 1.3, min_neighbors: int = 5) -> List[Tuple[int, int, int, int]]:
    """Detects faces in an image using a cascade classifier."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return cascade.detectMultiScale(gray, scale_factor, min_neighbors)


def draw_rectangles(image: any, rectangles: List[Tuple[int, int, int, int]], color: Tuple[int, int, int] = (0, 255, 0)) -> None:
    """Draws rectangles on the image."""
    for (x, y, w, h) in rectangles:
        cv2.rectangle(image, (x, y), (x + w, y + h), color, 2)


def process_frame(camera: cv2.VideoCapture, cascade: cv2.CascadeClassifier) -> Tuple[bool, any]:
    """Reads a frame, detects faces, and draws rectangles."""
    read, frame = camera.read()
    if not read:
        return False, frame
    faces = detect_faces(frame, cascade)
    draw_rectangles(frame, faces)
    return True, frame


def main(window_title: str = "Face Detection", cascade_path: str = "haarcascade_frontalface_default.xml") -> None:
    """Main function for face detection."""
    try:
        with open_camera() as camera:
            cascade = load_cascade(cascade_path)
            cv2.namedWindow(window_title, cv2.WINDOW_NORMAL)
            cv2.resizeWindow(window_title, 800, 600)

            while True:
                success, frame = process_frame(camera, cascade)
                if not success:
                    print("Failed to grab frame")
                    break

                cv2.imshow(window_title, frame)
                if cv2.waitKey(1) & 0xFF == ord('q'):
                    break

    except (IOError, KeyboardInterrupt) as e:
        print(f"Error: {e}")
    finally:
        cv2.destroyAllWindows()


if __name__ == "__main__":
    main()

