import time
import spidev
import smbus2 as smbus
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

# SPI configuration for the MCP3008 ADC
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 50000

# I2C configuration for the OLED display
I2C_BUS = 1
I2C_ADDRESS = 0x3C

# Initialize SPI
def init_spi():
    """Initialize the SPI interface."""
    spi = spidev.SpiDev()
    try:
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        return spi
    except Exception as e:
        print(f"Error initializing SPI: {e}")
        return None

# Initialize I2C OLED display
def init_oled():
    """Initialize the I2C OLED display."""
    try:
        serial = i2c(port=I2C_BUS, address=I2C_ADDRESS)
        display = ssd1306(serial)
        return display
    except Exception as e:
        print(f"Error initializing OLED: {e}")
        return None

# Read ADC channel
def read_adc_channel(spi, channel):
    """Read a single channel from the MCP3008 ADC."""
    if channel < 0 or channel > 7:
        raise ValueError("Invalid ADC channel. Must be between 0 and 7.")

    try:
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

# Convert ADC reading to voltage
def convert_to_voltage(adc_value):
    """Convert ADC reading to voltage."""
    if adc_value is None:
        return None
    voltage = adc_value * (3.3 / 1023.0)
    return voltage

# Display voltages on OLED
def display_voltages(display, voltages):
    """Display the voltages on the OLED screen."""
    if display is None:
        return

    try:
        with canvas(display) as draw:
            for i, voltage in enumerate(voltages):
                draw.text((0, i * 10), f"Ch {i}: {voltage:.2f}V", fill="white")
    except Exception as e:
        print(f"Error displaying voltages: {e}")

def main():
    """Main function to read ADC and display voltages."""
    spi = init_spi()
    display = init_oled()

    if spi is None or display is None:
        print("Failed to initialize SPI or OLED. Exiting.")
        return

    try:
        while True:
            voltages = []
            for channel in range(4):
                adc_value = read_adc_channel(spi, channel)
                voltage = convert_to_voltage(adc_value)
                if voltage is not None:
                    voltages.append(voltage)
                else:
                    voltages.append("Error")

            display_voltages(display, voltages)
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if spi:
            spi.close()
        print("Program finished.")

if __name__ == "__main__":
    main()

