            time.sleep(2)

    except KeyboardInterrupt:
        print("Exiting program")
    finally:
        # Clear the OLED display and release resources
        oled_display.fill(0)
        oled_display.show()
        i2c_bus.deinit()

if __name__ == "__main__":
    main()

