import time
import board
import busio
import adafruit_bmp280
import RPi.GPIO as GPIO

# Define GPIO pins for LEDs
LED_PINS = [17, 27, 22]

# Define pressure thresholds (hPa)
LOW_PRESSURE = 990
NORMAL_PRESSURE = 1010

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        log_error(f"I2C initialization failed: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor."""
    try:
        bmp280 = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
        time.sleep(1)  # Allow sensor to stabilize
        return bmp280
    except Exception as e:
        log_error(f"BMP280 initialization failed: {e}")
        return None

def initialize_gpio(led_pins):
    """Initialize GPIO pins for LEDs."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in led_pins:
            GPIO.setup(pin, GPIO.OUT)
            GPIO.output(pin, GPIO.LOW)  # Initialize LEDs to off
    except Exception as e:
        log_error(f"GPIO initialization failed: {e}")
        return False
    return True

def read_pressure(bmp280_sensor):
    """Read pressure from the BMP280 sensor."""
    try:
        return bmp280_sensor.pressure
    except Exception as e:
        log_error(f"Pressure reading failed: {e}")
        return None

def update_leds(pressure, led_pins):
    """Update LEDs based on pressure levels."""
    try:
        if pressure is not None:
            if pressure < LOW_PRESSURE:
                GPIO.output(led_pins[0], GPIO.HIGH)
                GPIO.output(led_pins[1], GPIO.LOW)
                GPIO.output(led_pins[2], GPIO.LOW)
            elif LOW_PRESSURE <= pressure < NORMAL_PRESSURE:
                GPIO.output(led_pins[0], GPIO.LOW)
                GPIO.output(led_pins[1], GPIO.HIGH)
                GPIO.output(led_pins[2], GPIO.LOW)
            else:
                GPIO.output(led_pins[0], GPIO.LOW)
                GPIO.output(led_pins[1], GPIO.LOW)
                GPIO.output(led_pins[2], GPIO.HIGH)
    except Exception as e:
        log_error(f"LED update failed: {e}")

def log_error(message):
    """Log errors to a file with timestamp."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open("error.log", "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"Error logging failed: {e}")

def main():
    """Main function to read pressure and control LEDs."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Failed to initialize I2C. Exiting.")
        return

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        print("Failed to initialize BMP280. Exiting.")
        return

    if not initialize_gpio(LED_PINS):
        print("Failed to initialize GPIO. Exiting.")
        return

    try:
        while True:
            pressure = read_pressure(bmp280_sensor)
            if pressure is not None:
                print(f"Pressure: {pressure:.2f} hPa")
                update_leds(pressure, LED_PINS)
            time.sleep(5)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        log_error(f"An unexpected error occurred: {e}")
    finally:
        # Cleanup GPIO on exit
        GPIO.cleanup()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

