import time
import board
import busio
import adafruit_bmp280

# Configuration
BASELINE_SAMPLE_DURATION = 10  # seconds
BASELINE_SAMPLE_INTERVAL = 1  # seconds
MIN_BASELINE_READINGS = 3

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor."""
    try:
        bmp280_sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus)
        return bmp280_sensor
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def read_baseline_pressure(bmp280_sensor):
    """Read baseline pressure from the BMP280 sensor."""
    baseline_pressures = []
    print(f"Collecting baseline pressure for {BASELINE_SAMPLE_DURATION} seconds. Do not move the sensor!")

    for _ in range(BASELINE_SAMPLE_DURATION):
        try:
            pressure = bmp280_sensor.pressure
            baseline_pressures.append(pressure)
            time.sleep(BASELINE_SAMPLE_INTERVAL)
        except Exception as e:
            print(f"Error reading pressure during baseline calibration: {e}")
            return None  # Indicate failure

    # Exclude the first two readings to avoid initial instability
    if len(baseline_pressures) > MIN_BASELINE_READINGS:
        baseline_pressure = sum(baseline_pressures[2:]) / (len(baseline_pressures) - 2)
        return baseline_pressure
    else:
        print("Not enough valid pressure readings to calculate baseline.")
        return None

def read_altitude(bmp280_sensor, baseline_pressure):
    """Read and calculate altitude from the BMP280 sensor."""
    try:
        altitude = bmp280_sensor.altitude
        relative_altitude = altitude - baseline_pressure  # Calculate relative altitude
        return relative_altitude
    except Exception as e:
        print(f"Error reading altitude: {e}")
        return None

def main():
    """Main function to read and display altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    bmp280_sensor = initialize_bmp280(i2c_bus)
    if bmp280_sensor is None:
        return  # Exit if BMP280 initialization failed

    baseline_pressure = read_baseline_pressure(bmp280_sensor)
    if baseline_pressure is None:
        return  # Exit if baseline pressure reading failed

    print("Baseline pressure established. Monitoring altitude...")

    try:
        while True:
            relative_altitude = read_altitude(bmp280_sensor, baseline_pressure)
            if relative_altitude is not None:
                print(f"Relative Altitude: {relative_altitude:05.2f} meters")
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # No specific cleanup needed for I2C or BMP280 in this library,
        # but including a placeholder for potential future expansion.
