import time
import signal
import sys
from gpiozero import PWMOutputDevice, CPUTemperature, GPIOZeroError

# Configuration (adjust these values as needed)
FAN_GPIO_PIN = 18  # GPIO pin connected to the fan's PWM control
ON_THRESHOLD_TEMP = 40.0  # Temperature (°C) above which the fan runs at full speed
LOW_SPEED_DUTY_CYCLE = 20  # Fan speed (%) below the threshold temperature
POLLING_INTERVAL = 5  # How often to check the temperature (seconds)
DEFAULT_TEMP = 25.0  # Default temperature if reading fails

# Global variable to store the fan object
fan = None
cpu = None

def setup():
    """Initializes the fan and CPU temperature sensor."""
    global fan, cpu
    try:
        fan = PWMOutputDevice(FAN_GPIO_PIN)
        cpu = CPUTemperature()
        print("Fan control initialized.")
    except GPIOZeroError as e:
        print(f"Error during setup: {e}")
        cleanup()  # Clean up resources before exiting
        sys.exit(1)

def get_fan_speed(cpu_temp):
    """Decides the fan speed based on the CPU temperature."""
    if cpu_temp > ON_THRESHOLD_TEMP:
        return 100
    else:
        return LOW_SPEED_DUTY_CYCLE

def set_fan_speed(speed):
    """Sets the fan speed."""
    try:
        fan.value = speed / 100.0
        print(f"Fan speed set to: {speed}%")
    except GPIOZeroError as e:
        print(f"Error setting fan speed: {e}")

def read_cpu_temperature():
    """Reads the CPU temperature."""
    try:
        return cpu.temperature
    except GPIOZeroError:
        print("Error reading CPU temperature. Using default.")
        return DEFAULT_TEMP

def control_fan():
    """Continuously monitors CPU temperature and adjusts fan speed."""
    try:
        while True:
            cpu_temp = read_cpu_temperature()
            fan_speed = get_fan_speed(cpu_temp)
            set_fan_speed(fan_speed)
            time.sleep(POLLING_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        cleanup()

def cleanup():
    """Resets the fan to a safe state and releases resources."""
    print("Cleaning up...")
    if fan:
        try:
            fan.close()  # Stop PWM and release the pin
            print("Fan pin released.")
        except Exception as e:
            print(f"Error during cleanup: {e}")

if __name__ == "__main__":
    setup()
    control_fan()

