#!/usr/bin/python3

"""
Control an LED based on a switch connected to an MCP23017 I2C GPIO expander.

This script reads the state of a switch connected to a GPIO pin on the MCP23017
and controls an LED connected to another GPIO pin on the MCP23017.

It uses an object-oriented approach for better structure and maintainability.
"""

import time
import sys
import smbus

# Constants
DEFAULT_I2C_BUS = 0  # Default I2C bus number
DEFAULT_MCP23017_ADDRESS = 0x27  # Default MCP23017 I2C address
DEFAULT_POLL_INTERVAL_SECONDS = 0.1  # Time between switch readings
LED_PIN = 0  # GPA0
SWITCH_PIN = 7  # GPB7


class MCP23017:
    """Represents the MCP23017 I2C GPIO expander."""

    def __init__(self, bus_number, address):
        """Initializes the MCP23017 object."""
        self.bus_number = bus_number
        self.address = address
        self.bus = None

    def begin(self):
        """Initializes communication with the MCP23017."""
        try:
            self.bus = smbus.SMBus(self.bus_number)
        except FileNotFoundError:
            raise IOError(f"I2C bus {self.bus_number} not found. Check your Raspberry Pi configuration.")
        return self

    def write_pin(self, pin, value):
        """Writes a value to a GPIO pin."""
        if not self.bus:
            raise IOError("MCP23017 not initialized. Call begin() first.")

        register = 0x12 if pin < 4 else 0x13  # GPA0-3: 0x12, GPB4-7: 0x13
        try:
            self.bus.write_byte_data(self.address, register, value)
        except IOError as e:
            raise IOError(f"Error writing to MCP23017: {e}")

    def read_pin(self, pin):
        """Reads the value of a GPIO pin."""
        if not self.bus:
            raise IOError("MCP23017 not initialized. Call begin() first.")

        register = 0x00 if pin < 4 else 0x01  # GPA0-3: 0x00, GPB4-7: 0x01
        try:
            return self.bus.read_byte_data(self.address, register)
        except IOError as e:
            raise IOError(f"Error reading from MCP23017: {e}")


class LEDController:
    """Controls an LED based on a switch state."""

    def __init__(self, mcp, switch_pin, led_pin, poll_interval):
        """Initializes the LEDController object."""
        self.mcp = mcp
        self.switch_pin = switch_pin
        self.led_pin = led_pin
        self.poll_interval = poll_interval
        self.mcp.write_pin(0x07, 0x90)  # Enable pull-up resistor on switch

    def run(self):
        """Runs the main control loop."""
        print("Starting LED control loop. Press Ctrl+C to exit.")
        try:
            while True:
                self.update_led_state()
                time.sleep(self.poll_interval)
        except KeyboardInterrupt:
            print("\nExiting program.")
        finally:
            self.cleanup()

    def update_led_state(self):
        """Reads the switch state and updates the LED."""
        try:
            switch_state = self.mcp.read_pin(self.switch_pin)
            if (switch_state & (1 << self.switch_pin)) == 0:  # Switch is active low
                self.mcp.write_pin(self.led_pin, 0xFF if self.led_pin == 0 else 0x01) # Set LED on
                print("Led ON")
            else:
                self.mcp.write_pin(self.led_pin, 0x00 if self.led_pin == 0 else 0xFE) # Set LED off
                print("Led OFF")

        except IOError as e:
            print(f"I2C error: {e}")
            # Implement retry logic or other error handling as needed

    def cleanup(self):
        """Performs any necessary cleanup before exiting."""
        print("Performing cleanup...")
        try:
            self.mcp.write_pin(self.led_pin, 0x00 if self.led_pin == 0 else 0xFE)  # Turn LED off
        except IOError as e:
            print(f"I2C error during cleanup: {e}")
        print("Cleanup complete.")


def main():
    """Main function to parse arguments and start the LED controller."""
    try:
        import argparse
        parser = argparse.ArgumentParser(description="Control an LED based on a switch connected to an MCP23017 I2C GPIO expander.")
        parser.add_argument("-b", "--bus", type=int, default=DEFAULT_I2C_BUS, help="The I2C bus number the MCP23017 is connected to (default: 0)")
        parser.add_argument("-a", "--address", type=lambda x: int(x, 16), default=DEFAULT_MCP23017_ADDRESS, help="The I2C address of the MCP23017 (default: 0x27)")
        parser.add_argument("-i", "--interval", type=float, default=DEFAULT_POLL_INTERVAL_SECONDS, help="Time in seconds between switch readings (default: 0.1)")
        args = parser.parse_args()

        mcp = MCP23017(args.bus, args.address).begin()
        controller = LEDController(mcp, SWITCH_PIN, LED_PIN, args.interval)
        controller.run()

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

