import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom module

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # seconds

# Global variables
log_file = None
recording = False
dog = None  # DOG object

# Documentation Dictionary (improved formatting)
MANUAL = {
    "help": "Call 'help <command>' for details.\nCommands: display, help, send, start, stop, write, exit",
    "start": "Starts recording data to a file.\nUsage: start <filename>",
    "stop": "Stops recording data.\nUsage: stop",
    "display": "Displays the contents of the log file.\nUsage: display",
    "send": "Sends data via DOGProtocol.\nUsage: send <data>",
    "write": "Writes data directly to the log file.\nUsage: write <data>",
    "exit": "Exits the program.\nUsage: exit",
}


def initialize_dog():
    """Initializes the DOGProtocol stack."""
    global dog
    try:
        dog = DOG.DOGProtocol()
        dog.start()  # Start the DOG threads
        return True
    except Exception as e:
        print(f"Error initializing DOGProtocol: {e}")
        return False


def safe_file_operation(func):
    """Decorator for safe file operations with error handling."""
    def wrapper(filename, *args, **kwargs):
        try:
            with open(filename, 'a+') as f:
                return func(f, *args, **kwargs)
        except FileNotFoundError:
            print(f"Error: File not found - {filename}")
        except IOError as e:
            print(f"Error writing to file: {e}")
    return wrapper


@safe_file_operation
def write_to_log(file, data):
    """Writes data to the log file."""
    file.seek(0, 2)  # Go to the end of the file
    file.write(data + "\n")


def log_data():
    """Continuously logs data from DOGProtocol."""
    global recording
    while recording:
        try:
            data = dog.receive()
            if data:  # Check if data is not empty
                write_to_log(log_file, data)
        except Exception as e:
            print(f"Error receiving data: {e}")
            time.sleep(POLL_INTERVAL)  # Avoid excessive error printing
    print("Logging stopped.")


def start_logging(filename):
    """Starts the data logging process."""
    global log_file, recording
    if recording:
        print("Already recording.")
        return

    try:
        open(filename, 'x')  # Check if file exists and create if it doesn't
    except FileExistsError:
        pass
    except OSError as e:
        print(f"Error creating/checking file: {e}")
        return

    log_file = filename
    recording = True
    print(f"Recording to {filename}")

    log_thread = threading.Thread(target=log_data, daemon=True)
    log_thread.start()


def stop_logging():
    """Stops the data logging process."""
    global recording
    recording = False
    if log_thread.is_alive():
        log_thread.join()  # Wait for the logging thread to finish
    print("Stopped logging.")


@safe_file_operation
def display_log(file):
    """Displays the contents of the log file."""
    file.seek(0)
    print(file.read())


def send_data(data):
    """Sends data via DOGProtocol."""
    global dog
    if not dog:
        print("DOGProtocol not initialized.")
        return
    try:
        dog.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_direct(data):
    """Writes data directly to the log file."""
    global log_file
    if not log_file:
        print("Not recording. Start logging first.")
        return
    write_to_log(log_file, data)
    print(f"Wrote: {data}")


def cleanup():
    """Cleans up GPIO and exits."""
    global dog
    print("Exiting...")
    if dog:
        dog.stop()  # Stop DOG threads
    GPIO.cleanup()
    sys.exit()


def show_help(command=None):
    """Displays help information."""
    if command and command in MANUAL:
        print(MANUAL[command])
    elif not command:
        print(MANUAL["help"])


def process_command(command):
    """Processes user commands."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()
    args = parts[1:]

    if cmd == "start":
        start_logging(" ".join(args)) if args else print("Usage: start <filename>")
    elif cmd == "stop":
        stop_logging()
    elif cmd == "display":
        display_log(log_file)
    elif cmd == "send":
        send_data(" ".join(args)) if args else print("Usage: send <data>")
    elif cmd == "write":
        write_direct(" ".join(args)) if args else print("Usage: write <data>")
    elif cmd == "exit":
        cleanup()
    elif cmd == "help":
        show_help(" ".join(args)) if args else show_help()
    else:
        print("Invalid command.")


def main():
    """Main function to run the data logger."""
    global log_thread

    if not initialize_dog():
        sys.exit(1)

    try:
        while True:
            command = input("JAYES@ROVER53:\t")
            process_command(command)
    except KeyboardInterrupt:
        cleanup()
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        cleanup()


if __name__ == "__main__":
    main()

