import RPi.GPIO as GPIO
import requests
import time

# Pin connected to the voltage sensor (BCM numbering)
VOLTAGE_SENSOR_PIN = 17

# Remote server URL for sending alerts
ALERT_ENDPOINT = 'http://example.com/alert'

def setup_gpio():
    """Configure the GPIO pin for the voltage sensor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(VOLTAGE_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def check_power_status():
    """Read the voltage sensor and return True if power is lost."""
    return GPIO.input(VOLTAGE_SENSOR_PIN) == GPIO.LOW

def send_power_failure_alert():
    """Send an HTTP POST request to the alert endpoint."""
    try:
        requests.post(ALERT_ENDPOINT, json={'alert': 'Power failure detected'}, timeout=5)
        print("Power failure alert sent successfully.")
    except requests.RequestException as request_error:
        print(f"Failed to send alert: {request_error}")

def main_loop():
    """Continuously monitor the voltage sensor and send alerts on power loss."""
    try:
        while True:
            if check_power_status():
                print("Power failure detected!")
                send_power_failure_alert()
            else:
                print("Power is present.")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Monitoring stopped by user.")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    setup_gpio()
    main_loop()

