# example-tft144-grfx.py          V1.7
# Functional implementation of TFT144 demo

import RPi.GPIO as GPIO
import spidev
import time
import logging
import signal
import sys
from typing import Tuple, Callable

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
RESET_PIN = 18
CHIP_ENABLE_PIN = 0  # 0 or 1 for CE0 / CE1
DATA_COMMAND_PIN = 22  # Labeled on board as "A0"
BACKLIGHT_PIN = 23  # LED backlight control

# Color constants as tuples
COLOR_WHITE = (255, 255, 255)
COLOR_BLACK = (0, 0, 0)
COLOR_RED = (255, 0, 0)
COLOR_BLUE = (0, 0, 255)
COLOR_GREEN = (0, 255, 0)
COLOR_PINK = (255, 105, 180)
COLOR_LIGHTBLUE = (3, 169, 244)
COLOR_LIGHTGREEN = (144, 238, 144)
COLOR_YELLOW = (255, 255, 0)
COLOR_MAGENTA = (255, 0, 255)
COLOR_CYAN = (0, 255, 255)

# Default orientation
ORIENTATION = 90

# Panel boundaries
X_MIN = 0
Y_MIN = 0
X_MAX = 128
Y_MAX = 128

# Font dimensions
FONT_WIDTH = 6
FONT_HEIGHT = 8

# Global variables (avoid where possible, but some are necessary for state)
spi = None  # SPI object
gpio = None # GPIO object

# Font data (example, replace with actual font)
FONT = [
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00,  # space
    0x00, 0x00, 0x5F, 0x00, 0x00, 0x00,  # !
    # ... (rest of the font data)
]


def initialize_gpio() -> None:
    """Initializes GPIO pins."""
    try:
        gpio.setmode(gpio.BCM)
        gpio.setwarnings(False)
        gpio.setup(RESET_PIN, gpio.OUT)
        gpio.setup(DATA_COMMAND_PIN, gpio.OUT)
        gpio.setup(BACKLIGHT_PIN, gpio.OUT)
        gpio.output(BACKLIGHT_PIN, gpio.HIGH)  # Turn on backlight
    except Exception as e:
        logging.critical(f"GPIO initialization failed: {e}")
        raise


def initialize_spi(bus: int = 0, device: int = 0) -> spidev.SpiDev:
    """Initializes SPI communication."""
    try:
        spi = spidev.SpiDev()
        spi.open(bus, device)
        spi.max_speed_hz = 9000000  # Adjust as needed
        return spi
    except Exception as e:
        logging.critical(f"SPI initialization failed: {e}")
        raise


def digital_write(pin: int, value: int) -> None:
    """Writes a digital value to a GPIO pin."""
    try:
        gpio.output(pin, value)
    except Exception as e:
        logging.error(f"Error writing to GPIO pin {pin}: {e}")



def digital_read(pin: int) -> int:
    """Reads a digital value from a GPIO pin."""
    try:
        return gpio.input(pin)
    except Exception as e:
        logging.error(f"Error reading from GPIO pin {pin}: {e}")
        return -1 # Indicate an error


def pulse_reset(pin: int, pulses: int = 2) -> None:
    """Pulses the reset pin."""
    try:
        for _ in range(pulses):
            digital_write(pin, gpio.LOW)
            time.sleep(0.001)
            digital_write(pin, gpio.HIGH)
            time.sleep(0.001)
    except Exception as e:
        logging.error(f"Error pulsing reset pin: {e}")



def send_command(command: int) -> None:
    """Sends a command to the TFT display."""
    try:
        digital_write(DATA_COMMAND_PIN, gpio.LOW)  # Command mode
        spi.writebytes([command])
    except Exception as e:
        logging.error(f"Error sending command: {e}")



def send_data(data: int) -> None:
    """Sends data to the TFT display."""
    try:
        digital_write(DATA_COMMAND_PIN, gpio.HIGH) # Data mode
        spi.writebytes([data])
    except Exception as e:
        logging.error(f"Error sending data: {e}")



def write_command_data(command: int, data: int) -> None:
    """Writes command and data to the TFT display."""
    try:
        send_command(command)
        send_data(data)
    except Exception as e:
        logging.error(f"Error writing command/data: {e}")


def display_pixel(x: int, y: int, color: Tuple[int, int, int]) -> None:
    """Displays a pixel on the TFT screen."""
    try:
        if not (X_MIN <= x <= X_MAX and Y_MIN <= y <= Y_MAX):
            raise ValueError("Pixel coordinates out of bounds")

        write_command_data(0x2C, color[0])  # Write pixel command
        write_command_data(0x2C, color[1])
        write_command_data(0x2C, color[2])

    except ValueError as e:
        logging.error(e)
    except Exception as e:
        logging.error(f"Error displaying pixel: {e}")



def display_fill_screen(color: Tuple[int, int, int]) -> None:
    """Fills the screen with a given color."""
    try:
        for y in range(Y_MIN, Y_MAX):
            for x in range(X_MIN, X_MAX):
                display_pixel(x, y, color)
    except Exception as e:
        logging.error(f"Error filling screen: {e}")


def display_character(character: str, x: int, y: int, color: Tuple[int, int, int], background: Tuple[int, int, int] = COLOR_BLACK) -> None:
    """Displays a character on the screen."""
    try:
        if not isinstance(character, str) or len(character) != 1:
            raise ValueError("Input must be a single character.")

        char_code = ord(character)
        if not (0x20 <= char_code < 0x7F): # Basic printable ASCII
            raise ValueError("Character not supported by font.")

        char_code -= 0x20  # Adjust to font table start
        char_data = FONT[char_code * (FONT_WIDTH * FONT_HEIGHT) // 8:(char_code + 1) * (FONT_WIDTH * FONT_HEIGHT) // 8]

        for row in range(FONT_HEIGHT):
            for col in range(FONT_WIDTH):
                byte_index = row * FONT_WIDTH + col
                if byte_index < len(char_data):
                    bit = (char_data[byte_index // 8] >> (7 - (byte_index % 8))) & 0x01
                    if bit:
                        display_pixel(x + col, y + row, color)
                    else:
                        display_pixel(x + col, y + row, background)
    except ValueError as e:
        logging.error(e)
    except Exception as e:
        logging.error(f"Error displaying character: {e}")



def display_string(text: str, x: int, y: int, color: Tuple[int, int, int], background: Tuple[int, int, int] = COLOR_BLACK) -> None:
    """Displays a string on the screen."""
    try:
        if not isinstance(text, str):
            raise ValueError("Input must be a string.")

        for i, char in enumerate(text):
            display_character(char, x + i * (FONT_WIDTH + 1), y, color, background)
    except ValueError as e:
        logging.error(e)
    except Exception as e:
        logging.error(f"Error displaying string: {e}")


def display_draw_line(x0: int, y0: int, x1: int, y1: int, color: Tuple[int, int, int]) -> None:
    """Draws a line on the screen using Bresenham's algorithm."""
    try:
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy

        while True:
            display_pixel(x0, y0, color)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x0 += sx
            if e2 < dx:
                err += dx
                y0 += sy
    except Exception as e:
        logging.error(f"Error drawing line: {e}")


def display_draw_rectangle(x: int, y: int, width: int, height: int, color: Tuple[int, int, int]) -> None:
    """Draws a rectangle on the screen."""
    try:
        if width <= 0 or height <= 0:
            raise ValueError("Width and height must be positive.")

        display_draw_line(x, y, x + width - 1, y, color)  # Top
        display_draw_line(x, y, x, y + height - 1, color)  # Left
        display_draw_line(x + width - 1, y, x + width - 1, y + height - 1, color)  # Right
        display_draw_line(x, y + height - 1, x + width - 1, y + height - 1, color)  # Bottom
    except ValueError as e:
        logging.error(e)
    except Exception as e:
        logging.error(f"Error drawing rectangle: {e}")


def display_draw_filled_rectangle(x: int, y: int, width: int, height: int, color: Tuple[int, int, int]) -> None:
    """Draws a filled rectangle on the screen."""
    try:
        if width <= 0 or height <= 0:
            raise ValueError("Width and height must be positive.")

        for i in range(x, x + width):
            display_draw_line(i, y, i, y + height - 1, color)
    except ValueError as e:
        logging.error(e)
    except Exception as e:
        logging.error(f"Error drawing filled rectangle: {e}")


def display_clear_screen(color: Tuple[int, int, int] = COLOR_BLACK) -> None:
    """Clears the screen to a specified color."""
    try:
        display_fill_screen(color)
    except Exception as e:
        logging.error(f"Error clearing screen: {e}")


def set_screen_orientation(orientation: int = ORIENTATION) -> None:
    """Sets the screen orientation."""
    global ORIENTATION
    ORIENTATION = orientation
    try:
        if ORIENTATION == 90:
            write_command_data(0x36, 0x68)  # 90-degree rotation
        elif ORIENTATION == 180:
            write_command_data(0x36, 0x28)  # 180-degree rotation
        elif ORIENTATION == 270:
            write_command_data(0x36, 0x48)  # 270-degree rotation
        else:
            write_command_data(0x36, 0x08)  # Default rotation
    except Exception as e:
        logging.error(f"Error setting screen orientation: {e}")


def initialize_display() -> None:
    """Initializes the TFT display."""
    try:
        pulse_reset(RESET_PIN)
        write_command_data(0x01, 0x00)  # Software reset
        time.sleep(0.05)
        write_command_data(0x11, 0x00)  # Sleep exit
        time.sleep(0.5)

        write_command_data(0x3A, 0x05)  # Pixel format: 16-bit
        write_command_data(0x29, 0x00)  # Display on

        set_screen_orientation(ORIENTATION)
    except Exception as e:
        logging.critical(f"Display initialization failed: {e}")
        raise


def signal_handler(sig, frame):
    """Handles signals for graceful exit."""
    logging.info("Exiting gracefully...")
    global spi, gpio
    try:
        display_clear_screen(COLOR_BLACK)
    except:
        pass
    try:
        if spi:
            spi.close()
    except:
        pass
    try:
        if gpio:
            gpio.cleanup()
    except:
        pass
    sys.exit(0)


def main() -> None:
    """Main function to run the TFT display demo."""
    global spi, gpio

    signals = [signal.SIGHUP, signal.SIGTERM, signal.SIGINT]
    for sig in signals:
        signal.signal(sig, signal_handler)

    try:
        initialize_gpio()
        spi = initialize_spi()
        initialize_display()

        colors = [COLOR_BLUE, COLOR_RED, COLOR_GREEN, COLOR_PINK, COLOR_LIGHTBLUE, COLOR_LIGHTGREEN, COLOR_YELLOW, COLOR_MAGENTA, COLOR_CYAN]

        while True:
            for color in colors:
                display_fill_screen(color)
                time.sleep(1)

            display_clear_screen()
            time.sleep(1)

            display_string("Hello", 0, 0, COLOR_WHITE)
            time.sleep(2)

            display_clear_screen(COLOR_BLACK)
            display_draw_line(0, 0, X_MAX, Y_MAX, COLOR_WHITE)
            display_draw_line(0, Y_MAX, X_MAX, 0, COLOR_WHITE)
            time.sleep(2)

            display_clear_screen()
            display_draw_rectangle(10, 10, 108, 68, COLOR_WHITE)
            time.sleep(2)

            display_clear_screen()
            display_draw_filled_rectangle(25, 25, 78, 58, COLOR_PINK)
            time.sleep(2)

    except Exception as e:
        logging.critical(f"Unhandled exception: {e}")
    finally:
        signal_handler(signal.SIGINT, None)


if __name__ == "__main__":
    main()

