import zmq
import time
import logging
import os
import signal
import sys
from typing import Callable, Any, Dict, List, Union

try:
    import RPi.GPIO as GPIO
except ImportError:
    import mock_gpio as GPIO  # Use a mock library for non-RPi platforms
    GPIO.setwarnings(False)

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_SUBSCRIPTION_PREFIX = "subscriptions"
DEFAULT_CHANNEL_ID = "default_channel"
DEFAULT_SOCKET_PORT = 5556
DEFAULT_SERVER_ADDRESS = "127.0.0.1"
MAX_SUBSCRIPTION_NAME_LENGTH = 255
VALID_GPIO_PINS = [12, 13, 18, 19, 20, 21]  # Example valid pins
PWM_FREQUENCY = 1000  # Hz for PWM frequency

# Global variables (avoid if possible, but some are necessary for signal handlers)
subscriptions: Dict[str, List[Dict[str, Any]]] = {}  # type: Dict[str, List[Dict[str, Any]]]
subscription_handlers: Dict[str, Callable] = {}  # type: Dict[str, Callable]
running = True
last_msg_time = time.time()
context = None  # type: zmq.Context
error_output_pwm = None  # type: Union[GPIO.PWM, GPIO.Output]
error_output_state = False
error_output_inverted = False
gpio_pin_number = None  # type: int
pwm_flag = False


class SubscriptionHandler:
    """Handles subscriptions to data streams and manages callbacks."""

    def __init__(self, subscription_prefix: str = DEFAULT_SUBSCRIPTION_PREFIX):
        """
        Initializes the SubscriptionHandler.

        Args:
            subscription_prefix (str): The prefix used for subscription variables.
        """
        self.subscription_prefix = subscription_prefix
        self.subscriptions: Dict[str, List[Dict[str, Any]]] = {}  # store subscriptions by channel
        self.subscription_handlers: Dict[str, Callable] = {}  # store handlers by channel

    def handle_command(self, command: dict) -> None:
        """
        Handles commands related to subscriptions, updates, and control.

        Args:
            command (dict): A dictionary containing the command details.
                           Expected keys: 'action', 'channel_id', 'callback', 'kwargs'
        """
        global subscriptions, subscription_handlers

        action = command.get('action')
        channel_id = command.get('channel_id')

        if not action or not channel_id:
            logger.error("Invalid command: 'action' and 'channel_id' required.")
            return

        if action == 'SUBSCRIBE':
            self._subscribe(channel_id, command)
        elif action == 'UPDATE_KW':
            self._update_kwargs(channel_id, command)
        elif action == 'UNSUBSCRIBE':
            self._unsubscribe(channel_id, command)
        elif action == 'REMOVE_ALL_CBS':
            self._remove_all_callbacks(channel_id)
        elif action == 'RESET':
            self._reset_channel(channel_id)
        elif action == 'RESET_ALL':
            self._reset_all_channels()
        elif action in ('MUTE', 'UNMUTE'):
            self._mute_channel(channel_id, command)
        elif action in ('MUTE_ALL', 'UNMUTE_ALL'):
            self._mute_all_channels(command)
        elif action in ('PAUSE', 'RESTART'):
            self._pause_channel(channel_id, command)
        elif action in ('PAUSE_ALL', 'RESTART_ALL'):
            self._pause_all_channels(command)
        elif action in ('KILL', 'ASSASSIN'):
            self._kill_channel(channel_id)
        elif action in ('KILL_ALL', 'ASSASSIN_ALL'):
            self._kill_all_channels()
        else:
            logger.error(f"Unknown action: {action}")

        # Update global subscriptions and handlers after processing the command
        subscriptions = self.subscriptions
        subscription_handlers = self.subscription_handlers

    def _subscribe(self, channel_id: str, command: dict):
        """Subscribes to a data stream on a specific channel."""
        stream_filter = command.get('stream_filter')
        callback = command.get('callback')
        kwargs = command.get('kwargs', {})

        if not stream_filter or not callback:
            logger.error("Invalid SUBSCRIBE command: 'stream_filter' and 'callback' required.")
            return

        if not callable(callback):
            logger.error(f"Invalid callback for channel {channel_id}: {callback} is not callable.")
            return

        handler_name = callback.__name__

        if channel_id not in self.subscriptions:
            self.subscriptions[channel_id] = []
            self.subscription_handlers[channel_id] = handler_name
        else:
            logger.warning(
                f"Overriding existing handler for channel {channel_id}. "
                f"Previous handler: {self.subscription_handlers[channel_id]}, new handler: {handler_name}"
            )

        subscription = {
            'stream_filter': stream_filter,
            'callback': callback,
            'kwargs': kwargs,
            'state': {},
            'control': {'alert': True, 'pause': False},
            'kwargs_history': [kwargs],  # Store history of kwargs
            'last_msg': None,
            'last_alert': None
        }

        self.subscriptions[channel_id].append(subscription)
        logger.info(f"Subscribed to stream: {stream_filter} on channel: {channel_id} with handler: {handler_name}")

    def _unsubscribe(self, channel_id: str, _):
        """Unsubscribes from a data stream on a specific channel."""
        if channel_id in self.subscriptions:
            del self.subscriptions[channel_id]
            del self.subscription_handlers[channel_id]
            logger.info(f"Unsubscribed from channel: {channel_id}")
        else:
            logger.warning(f"Attempted to unsubscribe from non-existent channel: {channel_id}")

    def _update_kwargs(self, channel_id: str, command: dict):
        """Updates the keyword arguments for a specific subscription."""
        index = command.get('index')
        kwargs = command.get('kwargs', {})

        if index is None or not isinstance(index, int):
            logger.error("Invalid UPDATE_KW command: 'index' must be an integer.")
            return

        if channel_id not in self.subscriptions:
            logger.error(f"Channel {channel_id} not found for UPDATE_KW.")
            return

        try:
            subscription = self.subscriptions[channel_id][index]
            subscription['kwargs'].update(kwargs)
            subscription['kwargs_history'].append(subscription['kwargs'].copy()) # Append a copy to history
            logger.info(f"Updated kwargs for channel: {channel_id}, index: {index} with {kwargs}")
        except IndexError:
            logger.error(f"Invalid index {index} for channel {channel_id}.")

    def _remove_all_callbacks(self, channel_id: str, _):
        """Removes all callbacks for a specific channel."""
        if channel_id in self.subscriptions:
            self.subscriptions[channel_id] = []
            logger.info(f"Removed all callbacks for channel: {channel_id}")
        else:
            logger.warning(f"Attempted to remove callbacks from non-existent channel: {channel_id}")

    def _reset_channel(self, channel_id: str, _):
        """Resets the state of a specific channel."""
        if channel_id in self.subscriptions:
            for subscription in self.subscriptions[channel_id]:
                subscription['state'] = {}
            logger.info(f"Reset state for channel: {channel_id}")
        else:
            logger.warning(f"Attempted to reset non-existent channel: {channel_id}")

    def _reset_all_channels(self):
        """Resets the state of all channels."""
        for channel_id in self.subscriptions:
            for subscription in self.subscriptions[channel_id]:
                subscription['state'] = {}
        logger.info("Reset all channel states.")

    def _mute_channel(self, channel_id: str, command: dict):
        """Mutes or unmutes a specific channel."""
        action = command.get('action')

        if channel_id not in self.subscriptions:
            logger.error(f"Channel {channel_id} not found for MUTE/UNMUTE.")
            return

        try:
            subscription = self.subscriptions[channel_id][0]  # Assuming single subscription per channel for mute
            subscription['control']['alert'] = (action == 'UNMUTE')
            logger.info(f"{'Unmuted' if action == 'UNMUTE' else 'Muted'} channel: {channel_id}")
        except (IndexError, KeyError, TypeError):  # Handle potential errors
            logger.error(f"Could not mute/unmute channel {channel_id}.")

    def _mute_all_channels(self, command: dict):
        """Mutes or unmutes all channels."""
        action = command.get('action')
        mute_all = (action == 'MUTE_ALL')

        for channel_id in self.subscriptions:
            for subscription in self.subscriptions[channel_id]:
                subscription['control']['alert'] = not mute_all
        logger.info(f"{'Muted' if mute_all else 'Unmuted'} all channels.")

    def _pause_channel(self, channel_id: str, command: dict):
        """Pauses or restarts a specific channel."""
        action = command.get('action')

        if channel_id not in self.subscriptions:
            logger.error(f"Channel {channel_id} not found for PAUSE/RESTART.")
            return

        try:
            subscription = self.subscriptions[channel_id][0]  # Assuming single subscription per channel for pause
            subscription['control']['pause'] = (action == 'PAUSE')
            logger.info(f"{'Paused' if action == 'PAUSE' else 'Restarted'} channel: {channel_id}")
        except (IndexError, KeyError, TypeError):  # Handle potential errors
            logger.error(f"Could not pause/restart channel {channel_id}.")

    def _pause_all_channels(self, command: dict):
        """Pauses or restarts all channels."""
        action = command.get('action')
        pause_all = (action == 'PAUSE_ALL')

        for channel_id in self.subscriptions:
            for subscription in self.subscriptions[channel_id]:
                subscription['control']['pause'] = pause_all
        logger.info(f"{'Paused' if pause_all else 'Restarted'} all channels.")

    def _kill_channel(self, channel_id: str, _):
        """Removes a specific channel."""
        self._unsubscribe(channel_id, None)

    def _kill_all_channels(self):
        """Removes all channels."""
        self.subscriptions.clear()
        self.subscription_handlers.clear()
        logger.info("Removed all channels.")


def update_subscriptions(subscriptions: Dict[str, List[Dict[str, Any]]], channel_id: str, data: Any) -> None:
    """
    Updates the subscriptions with new data.

    Args:
        subscriptions (dict): The current subscriptions.
        channel_id (str): The ID of the channel to update.
        data (any): The data to use for the update.
    """
    global subscription_handlers

    if channel_id not in subscriptions:
        logger.warning(f"Channel {channel_id} not found in subscriptions.")
        return

    for subscription in subscriptions[channel_id]:
        handler_name = subscription.get('callback').__name__  # Assuming callback is directly stored
        if handler_name in subscription_handlers:
            try:
                subscription_handlers[handler_name](data, **subscription.get('kwargs', {}))
            except Exception as e:
                logger.error(f"Error calling handler {handler_name} for channel {channel_id}: {e}")
        else:
            logger.error(f"Handler {handler_name} not found for channel {channel_id}.")


class GracefulShutdown:
    """Handles SIGTERM and SIGINT signals for graceful shutdown."""

    def __init__(self, handler: Callable = None):
        """
        Initializes the GracefulShutdown handler.

        Args:
            handler (callable): A custom function to call on shutdown.
                                 If None, the default cleanup will be performed.
        """
        self.handler = handler
        self.original_handlers = {
            signal.SIGTERM: signal.default_int_handler,
            signal.SIGINT: signal.default_int_handler,
        }
        self._register()

    def _register(self):
        """Registers the signal handlers."""
        signal.signal(signal.SIGTERM, self._handle_signal)
        signal.signal(signal.SIGINT, self._handle_signal)

    def _ unregister(self):
        """Unregisters the signal handlers."""
        signal.signal(signal.SIGTERM, signal.SIG_DFL)
        signal.signal(signal.SIGINT, signal.SIG_DFL)

    def _handle_signal(self, signum, frame):
        """Handles the signals and calls the appropriate handler."""
        global running, context, error_output_pwm

        logger.info(f"Received signal {signum}. Shutting down gracefully...")

        running = False

        if self.handler:
            try:
                self.handler()
            except Exception as e:
                logger.error(f"Error in custom shutdown handler: {e}")

        # Clean up resources
        if context:
            context.term()
        if error_output_pwm:
            try:
                error_output_pwm.stop()
            except Exception:
                pass
        GPIO.cleanup()

        logger.info("Cleanup complete. Exiting.")
        sys.exit(0)


def initialize_zmq_socket(context: zmq.Context, address: str, port: int) -> zmq.Socket:
    """Initializes a ZMQ socket with retry logic."""
    sock = context.socket(zmq.PUB)
    sock.setsockopt(zmq.LINGER, 0)

