import time
import math
import numpy as np
from smbus2 import SMBus
import logging

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
MPU6050_ADDRESS = 0x68
POWER_MANAGEMENT_REGISTER = 0x6B
SENSOR_ADDRESS = 0x3B
I2C_BUS_NUMBER = 1
SAMPLE_RATE = 0.2  # seconds
NUM_SAMPLES = 15
WINDOW_SIZE = 10
ZSCORE_THRESHOLD = 3
MIN_STD_DEV = 1.0

def initialize_i2c_bus(bus_number: int) -> SMBus:
    """Initializes the I2C bus with error handling."""
    try:
        bus = SMBus(bus_number)
        return bus
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus: {e}")
        raise

def initialize_mpu6050(bus: SMBus, address: int) -> None:
    """Wakes up the MPU6050 sensor."""
    try:
        bus.write_byte_data(address, POWER_MANAGEMENT_REGISTER, 0)
    except Exception as e:
        logger.error(f"Failed to initialize MPU6050: {e}")
        raise

def read_raw_data(bus: SMBus, address: int, register: int) -> int:
    """Reads raw 16-bit data from the specified register."""
    try:
        high = bus.read_byte_data(address, register)
        low = bus.read_byte_data(address, register + 1)
        value = (high << 8) | low
        return value
    except Exception as e:
        logger.error(f"Failed to read data from register {register}: {e}")
        raise

def convert_to_gyroscope_data(bus: SMBus, address: int, register: int) -> float:
    """Converts raw gyroscope data to degrees per second."""
    try:
        raw_data = read_raw_data(bus, address, register)
        return raw_data / 131.0
    except Exception as e:
        logger.error(f"Failed to convert gyroscope data from register {register}: {e}")
        raise


def convert_to_accelerometer_data(bus: SMBus, address: int, register: int) -> float:
    """Converts raw accelerometer data to g-force units."""
    try:
        raw_data = read_raw_data(bus, address, register)
        return raw_data / 16384.0
    except Exception as e:
        logger.error(f"Failed to convert accelerometer data from register {register}: {e}")
        raise

def calculate_magnitude(x: float, y: float, z: float) -> float:
    """Calculates the magnitude of the accelerometer vector."""
    return math.sqrt(x**2 + y**2 + z**2)

def calculate_mean(data: list[float]) -> float:
    """Calculates the mean of a list of numbers."""
    return sum(data) / len(data) if data else 0

def calculate_std_dev(data: list[float], mean: float) -> float:
    """Calculates the standard deviation of a list of numbers."""
    return math.sqrt(sum([(x - mean)**2 for x in data]) / len(data)) if data else 0

def calculate_zscore(value: float, mean: float, std_dev: float) -> float:
    """Calculates the z-score of a value."""
    return (value - mean) / std_dev if std_dev != 0 else 0

def detect_anomaly(zscore: float, threshold: float) -> bool:
    """Detects if a z-score is an anomaly based on the threshold."""
    return abs(zscore) > threshold

def read_accelerometer_data(bus: SMBus, address: int) -> tuple[float, float, float]:
    """Reads accelerometer data from the MPU6050."""
    try:
        accel_x = convert_to_accelerometer_data(bus, address, SENSOR_ADDRESS)
        accel_y = convert_to_accelerometer_data(bus, address, SENSOR_ADDRESS + 2)
        accel_z = convert_to_accelerometer_data(bus, address, SENSOR_ADDRESS + 4)
        return accel_x, accel_y, accel_z
    except Exception as e:
        logger.error(f"Failed to read accelerometer data: {e}")
        raise


def main() -> None:
    """Main function to run the anomaly detection."""
    try:
        bus = initialize_i2c_bus(I2C_BUS_NUMBER)
        initialize_mpu6050(bus, MPU6050_ADDRESS)

        acceleration_magnitudes = []

        for _ in range(NUM_SAMPLES):
            accel_x, accel_y, accel_z = read_accelerometer_data(bus, MPU6050_ADDRESS)
            magnitude = calculate_magnitude(accel_x, accel_y, accel_z)
            acceleration_magnitudes.append(magnitude)
            time.sleep(SAMPLE_RATE)

        if len(acceleration_magnitudes) >= WINDOW_SIZE:
            window = acceleration_magnitudes[-WINDOW_SIZE:]
            mean = calculate_mean(window)
            std_dev = calculate_std_dev(window, mean) or MIN_STD_DEV

            for i in range(len(acceleration_magnitudes)):
                zscore = calculate_zscore(acceleration_magnitudes[i], mean, std_dev)
                if detect_anomaly(zscore, ZSCORE_THRESHOLD):
                    logger.warning(
                        f"Anomaly detected! Index: {i}, Value: {acceleration_magnitudes[i]:.2f}, "
                        f"Mean: {mean:.2f}, StdDev: {std_dev:.2f}, Z-Score: {zscore:.2f}"
                    )

    except Exception as e:
        logger.exception(f"An error occurred: {e}")
    finally:
        if 'bus' in locals():
            bus.close()

if __name__ == "__main__":
    main()

