#!/usr/bin/python3

import RPi.GPIO as GPIO
import time

class DcMotor:
    """
    Controls a DC motor connected to an L298N motor driver.

    Provides methods for controlling the motor's speed and direction.
    """

    MOTOR_IN1_PIN = None  # Set these in subclasses
    MOTOR_IN2_PIN = None
    MOTOR_PWM_PIN = None
    DEFAULT_PWM_FREQUENCY = 1000  # Hz

    def __init__(self, pwm_frequency=DEFAULT_PWM_FREQUENCY):
        """
        Initializes the DC motor object.

        Sets up the GPIO pins and PWM.
        """
        try:
            GPIO.setmode(GPIO.BCM)  # Use Broadcom pin numbering
            GPIO.setwarnings(False)  # Suppress warnings

            self._setup_gpio_pins()
            self.pwm = GPIO.PWM(self.MOTOR_PWM_PIN, pwm_frequency)
            self.pwm.start(0)  # Start with 0% duty cycle (motor stopped)
            self.current_duty_cycle = 0
            self.is_running = False
            self.pwm_frequency = pwm_frequency

        except Exception as e:
            raise RuntimeError(f"DCMotor initialization failed: {e}")

    def _setup_gpio_pins(self):
        """Sets up the GPIO pins for motor control."""
        try:
            GPIO.setup(self.MOTOR_IN1_PIN, GPIO.OUT)
            GPIO.setup(self.MOTOR_IN2_PIN, GPIO.OUT)
            GPIO.setup(self.MOTOR_PWM_PIN, GPIO.OUT)
        except Exception as e:
            raise RuntimeError(f"GPIO pin setup failed: {e}")

    def set_duty_cycle(self, duty_cycle):
        """
        Sets the motor's duty cycle.

        Args:
            duty_cycle: An integer between -255 and 255.
                          - Positive: Forward motion.
                          - Negative: Reverse motion.
                          - Zero: Stop.
        """
        try:
            if not (-255 <= duty_cycle <= 255):
                raise ValueError("Duty cycle must be between -255 and 255")

            if duty_cycle == self.current_duty_cycle:
                return  # No change

            self.current_duty_cycle = duty_cycle
            forward = duty_cycle > 0
            pwm_duty = abs(duty_cycle)

            if forward:
                self._set_forward()
            else:
                self._set_reverse()

            self.pwm.ChangeDutyCycle(pwm_duty)
            self.is_running = pwm_duty > 0

        except Exception as e:
            raise RuntimeError(f"Error setting duty cycle: {e}")


    def _set_forward(self):
        """Sets the motor direction to forward."""
        GPIO.output(self.MOTOR_IN1_PIN, GPIO.HIGH)
        GPIO.output(self.MOTOR_IN2_PIN, GPIO.LOW)

    def _set_reverse(self):
        """Sets the motor direction to reverse."""
        GPIO.output(self.MOTOR_IN1_PIN, GPIO.LOW)
        GPIO.output(self.MOTOR_IN2_PIN, GPIO.HIGH)


    def set_frequency(self, frequency):
        """
        Sets the PWM frequency.

        Args:
            frequency: The desired PWM frequency in Hz.
        """
        try:
            if not isinstance(frequency, int) or frequency <= 0:
                raise ValueError("Frequency must be a positive integer")
            self.pwm.ChangeFrequency(frequency)
            self.pwm_frequency = frequency
        except Exception as e:
            raise RuntimeError(f"Error setting frequency: {e}")

    def get_frequency(self):
        """Returns the current PWM frequency."""
        return self.pwm_frequency

    def stop(self):
        """Stops the motor."""
        self.set_duty_cycle(0)

    def close(self):
        """Stops the motor and cleans up GPIO pins."""
        self.stop()
        try:
            self.pwm.stop()
            GPIO.cleanup() # Clean up all GPIO pins used by this object.
        except Exception as e:
            print(f"GPIO cleanup failed: {e}")  # Report, but don't re-raise


class DcMotorExample(DcMotor):
    """Example implementation with specific pin assignments."""

    MOTOR_IN1_PIN = 18
    MOTOR_IN2_PIN = 23
    MOTOR_PWM_PIN = 12


if __name__ == "__main__":
    try:
        motor = DcMotorExample()

        print("DC Motor Control Example")
        print("Press Ctrl+C to exit.")

        while True:
            try:
                user_input = input("Enter duty cycle (-255-255, 'q' to quit, 'f' to set frequency): ").strip().lower()

                if user_input == 'q':
                    break
                elif user_input.startswith('f'):
                    try:
                        frequency = int(user_input[1:].strip())
                        motor.set_frequency(frequency)
                        print(f"PWM frequency set to {frequency} Hz")
                    except ValueError:
                        print("Invalid frequency. Use 'f<frequency>' format.")
                else:
                    try:
                        duty_cycle = int(user_input)
                        motor.set_duty_cycle(duty_cycle)
                        print(f"Duty cycle set to {duty_cycle}")
                    except ValueError:
                        print("Invalid input. Enter an integer duty cycle (-255-255).")

            except KeyboardInterrupt:
                print("\nExiting program.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")

    except RuntimeError as e:
        print(f"Error during motor setup: {e}")
    finally:
        if 'motor' in locals(): # Only cleanup if motor object was created
            motor.close()

