    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_seesaw(i2c_bus):
    """Initialize the Seesaw soil moisture sensor."""
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=I2C_ADDRESS)
        return sensor
    except Exception as e:
        print(f"Error initializing Seesaw sensor: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize the GPIO pin for the water pump."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pump_pin, GPIO.OUT)
        GPIO.output(pump_pin, GPIO.LOW)  # Initially turn off the pump
    except Exception as e:
        print(f"Error initializing GPIO: {e}")

def read_moisture_level(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        moisture = sensor.moisture_read()
        return moisture
    except Exception as e:
        print(f"Error reading moisture: {e}")
        return None

def control_water_pump(pump_pin, moisture_level, threshold):
    """Control the water pump based on the moisture level."""
    try:
        if moisture_level is not None:
            if moisture_level < threshold:
                GPIO.output(pump_pin, GPIO.HIGH)  # Turn on pump
                print("Water Pump ON: Soil too dry")
            else:
                GPIO.output(pump_pin, GPIO.LOW)  # Turn off pump
                print("Water Pump OFF: Soil moisture sufficient")
    except Exception as e:
        print(f"Error controlling water pump: {e}")

def main():
    """Main function to read sensor data and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_seesaw(i2c_bus)
    if sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture = read_moisture_level(sensor)
            if moisture is not None:
                print(f"Soil Moisture: {moisture}")
                control_water_pump(PUMP_GPIO_PIN, moisture, MOISTURE_THRESHOLD)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # Ensure pump is off and resources are released
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()
        print("GPIO and I2C resources released.")

if __name__ == "__main__":
    main()

