import smbus2
import time
import logging

# Logging for the I2C device helper
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

# I2C bus number on the Raspberry Pi (1 for older boards, 2 for newer boards)
DEFAULT_I2C_BUS_NUMBER = 1


class I2CDeviceError(Exception):
    """Base exception for I2C device errors."""
    pass


class I2CDeviceProbeError(I2CDeviceError):
    """Exception raised when probing the I2C device fails."""
    pass


class I2CDevice:
    """Generic I2C device helper that abstracts register access."""

    def __init__(self, address, bus_number=DEFAULT_I2C_BUS_NUMBER):
        # Store the device address and open the I2C bus
        self.address = address
        self.bus_number = bus_number
        self.i2c_bus = smbus2.SMBus(bus_number)
        # Probe the device to confirm it acknowledges the address
        if not self._probe_device():
            raise I2CDeviceProbeError("No I2C device found at address 0x%02X" % address)

    def _probe_device(self):
        """Attempt a quick read to confirm the device acknowledges its address."""
        # A non-zero read indicates the device is present on the bus
        try:
            return self.i2c_bus.read_byte(self.address) != 0
        except OSError:
            return False

    def write_byte(self, register, value):
        """Write a single byte to the given register on the device."""
        try:
            self.i2c_bus.write_byte_data(self.address, register, value)
        except OSError as bus_error:
            raise I2CDeviceError("Write failed: %s" % bus_error) from bus_error

    def read_byte(self, register):
        """Read a single byte from the given register on the device."""
        try:
            return self.i2c_bus.read_byte_data(self.address, register)
        except OSError as bus_error:
            raise I2CDeviceError("Read failed: %s" % bus_error) from bus_error

    def close(self):
        """Close the I2C bus connection to the device."""
        self.i2c_bus.close()

    def __enter__(self):
        """Support the context-manager protocol for automatic resource management."""
        return self

    def __exit__(self, exc_type, exc_value, exc_traceback):
        # Always close the bus when the context block exits
        self.close()


def main():
    # Open a 0x40 sensor on the default I2C bus and toggle a control bit
    try:
        sensor_device = I2CDevice(0x40)
        logging.info("I2C device ready at address 0x40")
        sensor_device.write_byte(0x00, 0x01)
        time.sleep(0.1)
        logging.info("Control byte: %02X", sensor_device.read_byte(0x00))
    except I2CDeviceError as device_error:
        logging.error("I2C error: %s", device_error)
    finally:
        # Ensure the bus is closed even if an error occurred
        if 'sensor_device' in locals():
            sensor_device.close()


if __name__ == "__main__":
    main()

