#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a robust and optimized driver for the DS1338 RTC chip.
"""

import smbus
from datetime import datetime, timedelta
import logging
import os
import signal

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_120MHZ = True
DEFAULT_BUS = 1
DEFAULT_ADDRESS = 0x68
REGISTERS = {
    "seconds": 0x00,
    "minutes": 0x01,
    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
    "control": 0x07,
    "status": 0x0F
}

# Global variable for the I2C bus
bus = None

def initialize_bus(bus_number=DEFAULT_BUS):
    """Initializes the I2C bus and handles potential errors."""
    global bus
    try:
        bus = smbus.SMBus(bus_number)
        return True
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus {bus_number}: {e}")
        return False


def get_rtc_object(bus_number=DEFAULT_BUS, address=DEFAULT_ADDRESS, century=21):
    """Creates and returns an RTC object.  Handles bus initialization."""
    if not initialize_bus(bus_number):
        raise RuntimeError("I2C bus initialization failed.")
    return DS1338(address, bus, century)


def cleanup():
    """Closes the I2C bus if it's open."""
    global bus
    if bus:
        try:
            bus.close()
            logger.info("I2C bus closed.")
        except Exception as e:
            logger.error(f"Error closing I2C bus: {e}")
        finally:
            bus = None



class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, address=DEFAULT_ADDRESS, bus=None, century=21):
        """Initializes the DS1338 RTC object."""
        self.address = address
        self._bus = bus
        self.century = century

    def _check_bus(self):
        """Checks if the bus is initialized."""
        if self._bus is None:
            raise RuntimeError("I2C bus not initialized. Call initialize_bus() or provide a bus object.")

    def _write_register(self, register, data):
        """Writes data to a specific register on the DS1338."""
        self._check_bus()
        try:
            self._bus.write_byte_data(self.address, register, data)
        except IOError as e:
            logger.error(f"I/O error writing to register 0x{register:02X}: {e}")
            raise

    def _read_register(self, register):
        """Reads data from a specific register on the DS1338."""
        self._check_bus()
        try:
            return self._bus.read_byte_data(self.address, register)
        except IOError as e:
            logger.error(f"I/O error reading from register 0x{register:02X}: {e}")
            raise


    def _bcd_to_int(self, bcd):
        """Converts Binary Coded Decimal (BCD) to integer."""
        try:
            return (bcd >> 4) * 10 + (bcd & 0x0F)
        except TypeError as e:
            logger.error(f"TypeError in bcd_to_int: {e}")
            return None

    def _int_to_bcd(self, integer):
        """Converts integer to Binary Coded Decimal (BCD)."""
        if not 0 <= integer <= 99:
            raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
        return (integer // 10 << 4) | (integer % 10)


    def _read_time_register(self, register):
        """Reads and converts a time register (seconds, minutes, etc.)."""
        return self._bcd_to_int(self._read_register(register))

    def _read_seconds(self):
        """Reads the seconds value."""
        return self._read_time_register(REGISTERS["seconds"])

    def _read_minutes(self):
        """Reads the minutes value."""
        return self._read_time_register(REGISTERS["minutes"])

    def _read_hours(self):
        """Reads the hours value."""
        return self._read_time_register(REGISTERS["hours"] & 0x3F)


    def _read_day(self):
        """Reads the day of the month."""
        return self._read_time_register(REGISTERS["date"])

    def _read_month(self):
        """Reads the month."""
        return self._read_time_register(REGISTERS["month"])


    def _read_year(self):
        """Reads the year."""
        return self._read_time_register(REGISTERS["year"])


    def read_all(self):
        """Reads all time and date components from the RTC."""
        try:
            year = self._read_year()
            month = self._read_month()
            day = self._read_day()
            hours = self._read_hours()
            minutes = self._read_minutes()
            seconds = self._read_seconds()
            return year, month, day, hours, minutes, seconds
        except Exception as e:
           logger.error(f"Error reading all RTC data: {e}")
           raise


    def _calculate_datetime(self, century=21):
        """Calculates a datetime object from the RTC data."""
        try:
            year, month, day, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year  # Add century
            return datetime(year, month, day, hours, minutes, seconds)
        except ValueError as e:  # Handle invalid date/time values
            logger.error(f"ValueError in calculate_datetime: {e}")
            return None


    def read_datetime(self, century=None):
        """Reads the current date and time as a datetime object."""
        century = century if century is not None else self.century
        return self._calculate_datetime(century)


    def _validate_time(self, seconds=None, minutes=None, hours=None, day=None, month=None, year=None):
        """Validates the time and date components."""
        if minutes is not None and not 0 <= minutes <= 59:
            raise ValueError("Minutes must be between 0 and 59.")
        if seconds is not None and not 0 <= seconds <= 59:
            raise ValueError("Seconds must be between 0 and 59.")
        if hours is not None and not 0 <= hours <= 23:
            raise ValueError("Hours must be between 0 and 23.")
        # ... (rest of the validation logic)


    def write_all(self, seconds=None, minutes=None, hours=None, day=None, month=None, year=None):
        """Writes all time and date components to the RTC."""
        self._validate_time(seconds, minutes, hours, day, month, year)

        try:
            if seconds is not None:
                self._write_register(REGISTERS["seconds"], self._int_to_bcd(seconds))
            if minutes is not None:
                self._write_register(REGISTERS["minutes"], self._int_to_bcd(minutes))
            if hours is not None:
                self._write_register(REGISTERS["hours"], self._int_to_bcd(hours))  # Omit 12/24h bit
            if day is not None:
                self._write_register(REGISTERS["day"], self._int_to_bcd(day))
            if month is not None:
                self._write_register(REGISTERS["month"], self._int_to_bcd(month))
            if year is not None:
                 self._write_register(REGISTERS["year"], self._int_to_bcd(year % 100)) # Store only last two digits

        except Exception as e:
            logger.error(f"Error writing to RTC: {e}")
            raise


    def write_seconds(self, seconds):
        """Writes the seconds value."""
        self._validate_time(seconds=seconds)
        self._write_register(REGISTERS["seconds"], self._int_to_bcd(seconds))

    # ... (similar methods for minutes, hours, day, month, year)


def main():
    """Example usage of the DS1338 RTC driver."""
    rtc = get_rtc_object()

    try:
        # Read the current time
        now = rtc.read_datetime()
        logger.info(f"Current date and time: {now}")

        # Set the time to 2 hours ago
        two_hours_ago = now - timedelta(hours=2)
        rtc.write_all(hours=two_hours_ago.hour, minutes=two_hours_ago.minute, seconds=two_hours_ago.second)
        logger.info("Time set to 2 hours ago.")

    except Exception as e:
        logger.error(f"An error occurred: {e}")

    finally:
        cleanup()


if __name__ == "__main__":
    main()

