    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
    "control": 0x07
}


def _bcd_to_int(bcd_value):
    """Converts BCD to integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logging.error(f"Invalid BCD value: {bcd_value}")
        return None


def _int_to_bcd(integer_value):
    """Converts integer to BCD."""
    if not 0 <= integer_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (integer_value // 10 << 4) | (integer_value % 10)


def _validate_time_component(value, min_val, max_val, component_name):
    """Validates time components."""
    if not min_val <= value <= max_val:
        raise ValueError(f"Invalid {component_name} value: {value}")
    return value


class DS1338:
    """Driver for the DS1338 Real-Time Clock (RTC) chip."""

    def __init__(self, i2c_bus=DEFAULT_I2C_BUS, device_address=DEFAULT_DEVICE_ADDRESS):
        """Initializes the DS1338 driver."""
        self.i2c_bus = i2c_bus
        self.device_address = device_address
        try:
            self.bus = smbus.SMBus(self.i2c_bus)
            logging.info(f"DS1338 initialized on I2C bus {self.i2c_bus} at address 0x{self.device_address:02X}")
        except Exception as e:
            logging.error(f"Failed to initialize DS1338: {e}")
            raise

    def _write_register(self, register_address, data):
        """Writes data to a specific register."""
        try:
            self.bus.write_byte_data(self.device_address, register_address, data)
            logging.debug(f"Wrote 0x{data:02X} to register 0x{register_address:02X}")
        except IOError as e:
            logging.error(f"I/O error writing to register 0x{register_address:02X}: {e}")
            raise

    def _read_register(self, register_address):
        """Reads data from a specific register."""
        try:
            data = self.bus.read_byte_data(self.device_address, register_address)
            logging.debug(f"Read 0x{data:02X} from register 0x{register_address:02X}")
            return data
        except IOError as e:
            logging.error(f"I/O error reading from register 0x{register_address:02X}: {e}")
            raise


    def _read_time_register(self, register_name):
        """Reads and converts a time register value."""
        register_address = REGISTERS[register_name]
        return _bcd_to_int(self._read_register(register_address))

    def read_all(self):
        """Reads all time components from the RTC."""
        try:
            year = self._read_time_register("year")
            month = self._read_time_register("month")
            date = self._read_time_register("date")
            day = self._read_time_register("day")
            hours = self._read_time_register("hours")
            minutes = self._read_time_register("minutes")
            seconds = self._read_time_register("seconds")

            # Handle potential None values returned by _bcd_to_int on error
            if None in (year, month, date, day, hours, minutes, seconds):
                raise IOError("Failed to read all RTC data.")

            return year, month, date, day, hours, minutes, seconds

        except IOError as e:
            logging.error(f"Error reading all RTC data: {e}")
            raise


    def read_datetime(self, century=21):
        """Reads the date and time and returns a datetime object."""
        try:
            year, month, date, _, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year  # Add century
            return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
        except ValueError as e:
            logging.error(f"Invalid time data: {e}")
            raise
        except IOError as e:
            logging.error(f"Error reading datetime: {e}")
            raise


    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Writes all time components to the RTC."""

        # Validate time components
        year = _validate_time_component(year, 0, 99, "year")
        month = _validate_time_component(month, 1, 12, "month")
        date = _validate_time_component(date, 1, 31, "date")
        day = _validate_time_component(day, 1, 7, "day")
        hours = _validate_time_component(hours, 0, 23, "hours")
        minutes = _validate_time_component(minutes, 0, 59, "minutes")
        seconds = _validate_time_component(seconds, 0, 59, "seconds")

        try:
            self._write_register(REGISTERS["seconds"], _int_to_bcd(seconds))
            self._write_register(REGISTERS["minutes"], _int_to_bcd(minutes))
            self._write_register(REGISTERS["hours"], _int_to_bcd(hours))  # 24-hour mode assumed
            self._write_register(REGISTERS["day"], _int_to_bcd(day))
            self._write_register(REGISTERS["date"], _int_to_bcd(date))
            self._write_register(REGISTERS["month"], _int_to_bcd(month))
            self._write_register(REGISTERS["year"], _int_to_bcd(year % 100)) # Store only last two digits

        except IOError as e:
            logging.error(f"Error writing all RTC data: {e}")
            raise


    def write_datetime(self, dt):
        """Writes the date and time from a datetime object."""
        try:
            self.write_all(
                dt.year % 100,  # Year (last two digits)
                dt.month,
                dt.day,
                dt.isoweekday(),
                dt.hour,
                dt.minute,
                dt.second,
            )
        except AttributeError:
            logging.error("Invalid datetime object provided.")
            raise
        except IOError as e:
            logging.error(f"Error writing datetime: {e}")
            raise


    def write_now(self):
        """Writes the current date and time to the RTC."""
        try:
            now = datetime.now(timezone.utc)
            self.write_datetime(now)
        except Exception as e:
            logging.error(f"Error writing current time: {e}")
            raise

    def close(self):
        """Closes the I2C bus connection."""
        try:
            self.bus.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")


def main():
    """Main function to demonstrate RTC usage."""
    try:
        rtc = DS1338()
        current_datetime = rtc.read_datetime()
        logging.info(f"Current date and time: {current_datetime}")
        rtc.close()
    except Exception as e:
        logging.error(f"An error occurred: {e}")


