import serial
import time
import pynmea2

# Configuration constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial_port(port, baudrate, timeout):
    """Initializes the serial port for GPS communication."""
    try:
        serial_connection = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        return serial_connection
    except serial.SerialException as serial_err:
        print(f"Serial port error: {serial_err}")
        return None


def parse_gps_data(serial_connection):
    """Reads and parses GPS data from the serial port."""
    try:
        nmea_data = serial_connection.readline().decode('ascii', errors='replace').strip()
        if nmea_data.startswith('$GPGGA'):
            msg = pynmea2.parse(nmea_data)
            return msg
        return None
    except Exception as parse_err:
        print(f"GPS data parsing error: {parse_err}")
        return None


def log_coordinates(log_file, latitude, longitude, altitude):
    """Logs GPS coordinates to a file."""
    try:
        with open(log_file, 'a') as logfile:
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
            log_entry = f"{timestamp} - Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m\n"
            logfile.write(log_entry)
    except IOError as log_err:
        print(f"File I/O error: {log_err}")


def main():
    """Main function to read, parse, and log GPS data."""
    serial_port = initialize_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_port is None:
        print("Failed to initialize serial port. Exiting.")
        return

    try:
        while True:
            gps_message = parse_gps_data(serial_port)

            if gps_message and gps_message.fix_quality == 1:
                latitude = gps_message.latitude
                longitude = gps_message.longitude
                altitude = gps_message.altitude

                print(f"Latitude: {latitude}, Longitude: {longitude}, Altitude: {altitude} m")
                log_coordinates(LOG_FILE, latitude, longitude, altitude)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

