import logging
import os
import serial
import time
import signal
from dataclasses import dataclass
from typing import Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
UART_DEVICE = "/dev/serial0"  # Raspberry Pi's UART device
BAUDRATE = 9600
TIMEOUT = 1
GPGGA_IDENTIFIER = "GPGGA"

# Global variable to control the main loop
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logging.info("Signal received, stopping...")
    running = False

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

@dataclass
class GPS_readings:
    """Represents GPS readings with latitude, longitude, altitude, and satellite count."""
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None

class GPSReader:
    """Reads and parses GPS data from a serial port."""

    def __init__(self, uart_device: str, baudrate: int, timeout: int):
        self.uart_device = uart_device
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port = None  # Initialize serial port

    def connect(self):
        """Connects to the serial port."""
        try:
            self.serial_port = serial.Serial(self.uart_device, self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to serial port: {self.uart_device}")
        except serial.SerialException as e:
            logging.error(f"Failed to connect to serial port: {e}")
            raise  # Re-raise the exception to be handled by the caller

    def disconnect(self):
        """Disconnects from the serial port and cleans up."""
        if self.serial_port and self.serial_port.is_open:
            self.serial_port.close()
            logging.info("Disconnected from serial port.")

    def read_gps_data(self) -> Optional[GPS_readings]:
        """Reads a line from the serial port and attempts to parse it as GPS data."""
        if not self.serial_port or not self.serial_port.is_open:
            logging.warning("Serial port is not open. Cannot read data.")
            return None

        try:
            line = self.serial_port.readline().decode('utf-8', errors='ignore').strip()
            if line.startswith(f"${GPGGA_IDENTIFIER},"):
                return self._parse_gpgga_sentence(line)
            else:
                return None  # Not a GPGGA sentence, ignore
        except serial.SerialException as e:
            logging.error(f"Serial port error while reading: {e}")
            return None
        except Exception as e:
            logging.error(f"Error reading GPS data: {e}")
            return None

    def _parse_gpgga_sentence(self, sentence: str) -> Optional[GPS_readings]:
        """Parses a GPGGA sentence and extracts GPS readings."""
        try:
            parts = sentence.split(',')
            if len(parts) != 15 or parts[0][3:] != GPGGA_IDENTIFIER:
                logging.warning(f"Invalid GPGGA sentence format: {sentence}")
                return None

            if parts[2] == '':
                logging.warning(f"Incomplete GPGGA sentence: {sentence}")
                return None

            latitude = self._parse_latitude(parts[2], parts[3])
            longitude = self._parse_longitude(parts[4], parts[5])
            altitude = self._parse_altitude(parts[9])
            satellites = self._parse_satellites(parts[7])

            return GPS_readings(latitude, longitude, altitude, satellites)

        except (ValueError, IndexError) as e:
            logging.error(f"Error parsing GPGGA sentence: {sentence} - {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error parsing GPGGA sentence: {sentence} - {e}")
            return None

    def _parse_latitude(self, latitude_str: str, latitude_direction: str) -> Optional[float]:
        """Parses the latitude value from the sentence."""
        try:
            degrees = int(latitude_str[:2])
            minutes = float(latitude_str[2:])
            decimal_degrees = degrees + (minutes / 60.0)
            if latitude_direction == 'S':
                decimal_degrees = -decimal_degrees
            return decimal_degrees
        except ValueError as e:
            logging.error(f"Invalid latitude format: {latitude_str} - {e}")
            return None

    def _parse_longitude(self, longitude_str: str, longitude_direction: str) -> Optional[float]:
        """Parses the longitude value from the sentence."""
        try:
            degrees = int(longitude_str[:3])
            minutes = float(longitude_str[3:])
            decimal_degrees = degrees + (minutes / 60.0)
            if longitude_direction == 'W':
                decimal_degrees = -decimal_degrees
            return decimal_degrees
        except ValueError as e:
            logging.error(f"Invalid longitude format: {longitude_str} - {e}")
            return None

    def _parse_altitude(self, altitude_str: str) -> Optional[float]:
        """Parses the altitude value from the sentence."""
        try:
            return float(altitude_str)
        except ValueError:
            return None

    def _parse_satellites(self, satellites_str: str) -> Optional[int]:
        """Parses the satellite count from the sentence."""
        try:
            return int(satellites_str)
        except ValueError:
            return None

def main():
    """Main function to read and process GPS data."""
    gps_reader = GPSReader(UART_DEVICE, BAUDRATE, TIMEOUT)

    try:
        gps_reader.connect()
        logging.info("Starting GPS data acquisition...")

        while running:
            gps_data = gps_reader.read_gps_data()
            if gps_data:
                logging.info(f"GPS Readings: Latitude={gps_data.latitude}, Longitude={gps_data.longitude}, "
                             f"Altitude={gps_data.altitude} meters, Satellites={gps_data.satellites}")
            time.sleep(1)  # Adjust sleep time as needed

    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        gps_reader.disconnect()
        logging.info("GPS data acquisition stopped.")

if __name__ == "__main__":
    main()

