    """Initializes the serial port with error handling."""
    try:
        return serial.Serial(port, baudrate=baudrate, timeout=timeout)
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port: {e}")
        raise

def power_on_gps(serial_port):
    """Powers on the GPS module."""
    try:
        serial_port.write(CNNS_ON_COMMAND)
        time.sleep(PAUSE_DURATION)  # Allow time for the module to respond
        logging.info("GPS powered on.")
        return True
    except serial.SerialException as e:
        logging.error(f"Failed to power on GPS: {e}")
        return False

def power_off_gps(serial_port):
    """Powers off the GPS module."""
    try:
        serial_port.write(CNNS_OFF_COMMAND)
        logging.info("GPS powered off.")
        return True
    except serial.SerialException as e:
        logging.error(f"Failed to power off GPS: {e}")
        return False

def read_gps_data(serial_port):
    """Reads data from the GPS module with error handling."""
    try:
        return serial_port.readline().decode('utf-8', errors='ignore').strip()
    except serial.SerialException as e:
        logging.error(f"Failed to read from serial port: {e}")
        return ""

def parse_gprmc_data(data):
    """Parses GPRMC data."""
    if not data:
        return None

    parts = data.split(",")
    if parts[0] == '$GPRMC' and parts[2] == VALID_GPRMC_STATUS:
        logging.debug(f"Valid GPRMC data received: {data}")
        return parts
    else:
        logging.debug(f"Invalid or incomplete GPRMC data: {data}")
        return None

class GPSDataError(Exception):
    """Custom exception for GPS data related errors."""
    pass

class GPSReader:
    """
    A class to read and parse GPS data from a serial port.
    """

    def __init__(self, port=UART_PORT, baudrate=UART_BAUDRATE):
        """Initializes the GPSReader object."""
        self.port = port
        self.baudrate = baudrate
        self.serial_port = None
        self.is_running = False

    def __enter__(self):
        """Context manager entry point."""
        self.open()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point."""
        self.close()

    def open(self):
        """Opens the serial port and powers on the GPS."""
        self.serial_port = initialize_serial(self.port, self.baudrate, READ_TIMEOUT)
        if self.serial_port:
            if power_on_gps(self.serial_port):
                self.is_running = True
                logging.info("GPSReader initialized successfully.")
            else:
                self.close()
                raise GPSDataError("Failed to power on GPS during initialization.")

    def close(self):
        """Closes the serial port and powers off the GPS."""
        if self.serial_port:
            if self.is_running:
                power_off_gps(self.serial_port)
            try:
                self.serial_port.close()
                logging.info("Serial port closed.")
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")
            finally:
                self.serial_port = None
                self.is_running = False

    def read_and_parse(self):
        """Reads data from the serial port and parses it."""
        if not self.is_running:
            raise GPSDataError("GPSReader is not initialized. Call open() first.")

        try:
            data = read_gps_data(self.serial_port)
            return parse_gprmc_data(data)
        except Exception as e:
            logging.error(f"Error reading and parsing GPS data: {e}")
            return None

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info("Signal received, shutting down...")
    global serial_port
    if serial_port:
        gps_reader = GPSReader()  # Create an instance to access the close method
        gps_reader.serial_port = serial_port # Assign the global serial port to the instance
        gps_reader.close()
    exit(0)

def main():
    """Main function to read and display GPS data."""

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with GPSReader() as gps_reader:
            while gps_reader.is_running:
                parsed_data = gps_reader.read_and_parse()
                if parsed_data:
                    logging.info(f"GPS Data: {parsed_data}")
                time.sleep(1)

    except GPSDataError as e:
        logging.error(f"GPS Data Error: {e}")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

