# Reads heart rate and SpO2 data from a UART-connected pulse oximeter on Raspberry Pi.

import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
DATA_BITS = serial.EIGHTBITS
PARITY_CHECK = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
TIMEOUT = 1  # seconds

def initialize_serial(port, baudrate, bytesize, parity, stopbits, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, bytesize, parity, stopbits, timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_pulse_oximeter_data(serial_port):
    """Reads and processes data from the pulse oximeter."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def process_data(line):
    """Parses the data and extracts heart rate and SpO2."""
    if line:
        try:
            heart_rate, spo2 = line.split(',')
            return heart_rate, spo2
        except ValueError:
            print(f"Invalid data format: {line}")
            return None, None
    return None, None

def display_data(heart_rate, spo2):
    """Displays the heart rate and SpO2 values."""
    if heart_rate and spo2:
        print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')

def main():
    """Main function to read and display pulse oximeter data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, DATA_BITS, PARITY_CHECK, STOP_BITS, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            data_line = read_pulse_oximeter_data(serial_connection)
            heart_rate, spo2 = process_data(data_line)
            display_data(heart_rate, spo2)
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nExiting program.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

