import serial
import time
import os
import sys

# Configuration for the serial port
SERIAL_PORT = '/dev/serial0'  # UART port on Raspberry Pi
BAUD_RATE = 9600
TIMEOUT = 1  # Timeout in seconds for reading data

# Log file name
LOG_FILE = 'power_consumption.log'

def configure_serial(port, baudrate, timeout):
    """Configures and returns a serial port object."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error configuring serial port: {e}")
        sys.exit(1)

def read_power_data(serial_port):
    """Reads a line from the serial port and returns the power value."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Warning: Non-numeric data received from meter.")
        return None
    except Exception as e:
        print(f"Error reading data: {e}")
        return None

def log_power_consumption(power, log_file):
    """Logs the power consumption to a file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} – Power: {power} W\n'
    try:
        with open(log_file, 'a') as file:
            file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log power consumption."""
    serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    try:
        while True:
            power_value = read_power_data(serial_connection)
            if power_value is not None:
                log_power_consumption(power_value, LOG_FILE)
                print(f'Power Consumption: {power_value} W')
            time.sleep(1)  # Wait for 1 second
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

