from http.server import BaseHTTPRequestHandler, HTTPServer
import json
import time
import serial
from typing import List, Dict, Any, Optional, Union

# Constants
SERVER_ADDRESS = ('', 8000)
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
MODEL_NAME = 'Web2uart Control'
DATA_STORE: List[Dict[str, Union[int, str, bool]]] = [
    {'id': 1, 'name': 'CHIPS', 'done': False},
    {'id': 2, 'name': 'garden', 'done': False}
]
SERIAL_TIMEOUT = 0.1  # Increased for more reliable reads


def handle_serial_command(command: str) -> Optional[str]:
    """Sends an SCPI command to the serial port and returns the response."""
    try:
        with serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT) as ser:
            ser.write(command.encode())
            time.sleep(0.1)  # Adjust delay as needed
            response = ser.read_all().decode('utf-8').strip()
            return response
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None


class MyHandler(BaseHTTPRequestHandler):
    """HTTP request handler for the web server."""

    def do_GET(self) -> None:
        """Handles GET requests."""
        if self.path == '/version':
            self._handle_version()
        elif self.path == '/getdata':
            self._handle_get_data()
        elif self.path.startswith('/getset/'):
            self._handle_get_set()
        elif self.path.startswith('/getpost/'):
            self._handle_get_post()
        elif self.path == '/postjson':
            self._handle_post_json()
        elif self.path == '/':
            self._handle_index()
        else:
            self._handle_not_found()

    def do_POST(self) -> None:
        """Handles POST requests."""
        if self.path == '/postjson':
            self._handle_post_json()
        else:
            self._handle_not_found()

    def _send_response(self, status_code: int, content: str, content_type: str) -> None:
        """Sends an HTTP response."""
        self.send_response(status_code)
        self.send_header('Content-Type', content_type)
        self.end_headers()
        self.wfile.write(content.encode())

    def _handle_version(self) -> None:
        """Handles the /version endpoint."""
        response = handle_serial_command("*IDN?\n")
        if response:
            html_content = f"<h1>Model Name: {MODEL_NAME}</h1><p>Version: {response}</p>"
            self._send_response(200, html_content, 'text/html')
        else:
            self._send_response(503, "Serial communication failed", 'text/plain')

    def _handle_get_data(self) -> None:
        """Handles the /getdata endpoint."""
        global DATA_STORE
        json_data = json.dumps(DATA_STORE)
        self._send_response(200, json_data, 'application/json')

    def _handle_get_set(self) -> None:
        """Handles the /getset/<id> endpoint."""
        try:
            item_id = int(self.path.split('/')[2])
        except (IndexError, ValueError):
            self._send_response(400, "Invalid item ID", 'text/plain')
            return

        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if item:
            json_data = json.dumps(item)
            self._send_response(200, json_data, 'application/json')
        else:
            self._send_response(404, "Item not found", 'text/plain')

    def _handle_get_post(self) -> None:
        """Handles the /getpost/<id>/<name> endpoint."""
        try:
            item_id, name = self._parse_path_params()
        except (ValueError, IndexError) as e:
            self._send_response(400, str(e), 'text/plain')
            return

        new_item = {'id': len(DATA_STORE) + 1, 'name': name, 'done': False}
        global DATA_STORE
        DATA_STORE.append(new_item)
        json_data = json.dumps(DATA_STORE)
        self._send_response(201, json_data, 'application/json')  # 201 Created

    def _handle_post_json(self) -> None:
        """Handles the /postjson endpoint."""
        content_length = int(self.headers.get('Content-Length', 0))
        post_data = self.rfile.read(content_length).decode('utf-8')

        try:
            data = json.loads(post_data)
            if not isinstance(data, list):
                raise ValueError("JSON data must be a list")

            global DATA_STORE
            DATA_STORE = data
            self._send_response(200, "Data updated successfully", 'text/plain')

        except (json.JSONDecodeError, ValueError) as e:
            self._send_response(400, f"Invalid JSON data: {e}", 'text/plain')

    def _handle_index(self) -> None:
        """Handles the root (/) endpoint."""
        html_content = "<h1>Welcome to the Web2uart Control</h1>"
        self._send_response(200, html_content, 'text/html')

    def _handle_not_found(self) -> None:
        """Handles not found endpoints."""
        self._send_response(404, "Not Found", 'text/plain')

    def _parse_path_params(self) -> tuple[int, str]:
        """Parses item ID and name from the URL path."""
        try:
            parts = self.path.split('/')
            item_id = int(parts[2])
            name = parts[3]
            return item_id, name
        except (IndexError, ValueError) as e:
            raise ValueError(f"Invalid path parameters: {e}")


def run_server(server_class: HTTPServer, handler_class: MyHandler) -> None:
    """Runs the HTTP server."""
    try:
        server_address = SERVER_ADDRESS
        httpd = server_class(server_address, handler_class)
        print(f'Starting server on {server_address[0]}:{server_address[1]}...')
        httpd.serve_forever()
    except Exception as e:
        print(f"Server error: {e}")
    finally:
        print("Shutting down server...")
        if 'httpd' in locals():
            httpd.server_close()


if __name__ == '__main__':
    run_server(HTTPServer, MyHandler)

